package lt.oneman.sync;

public class BirdHouseDecoder {
    public static final String[] BIRDHOUSE_NAMES = new String[]{"Bird House", "Oak Bird House", "Willow Bird House", "Teak Bird House", "Maple Bird House", "Mahogany Bird House", "Yew Bird House", "Magic Bird House", "Redwood Bird House"};

    public static State getState(int varp) {
        if (varp < 0 || varp > BIRDHOUSE_NAMES.length * 3) {
            return State.UNKNOWN;
        }
        if (varp == 0) {
            return State.EMPTY;
        }
        if (varp % 3 == 0) {
            return State.SEEDED;
        }
        return State.BUILT;
    }

    public static String getHouseName(int varp) {
        int index = (varp - 1) / 3;
        if (varp <= 0 || index < 0 || index >= BIRDHOUSE_NAMES.length) {
            return null;
        }
        return BIRDHOUSE_NAMES[index];
    }

    public static enum State {
        SEEDED,
        BUILT,
        EMPTY,
        UNKNOWN;

    }
}

package lt.oneman.sync;

import net.runelite.api.gameval.ItemID;

/** Presentation snapshot of the existing Time Tracking observation and 50-minute estimate. */
final class BirdhouseRun
{
    static final long DURATION=3000;
    static final String[] LOCATIONS={"Mushroom Meadow N","Mushroom Meadow S","Verdant Valley NE","Verdant Valley SW"};
    private static final int[] ITEMS={ItemID.BIRDHOUSE_NORMAL,ItemID.BIRDHOUSE_OAK,ItemID.BIRDHOUSE_WILLOW,ItemID.BIRDHOUSE_TEAK,
        ItemID.BIRDHOUSE_MAPLE,ItemID.BIRDHOUSE_MAHOGANY,ItemID.BIRDHOUSE_YEW,ItemID.BIRDHOUSE_MAGIC,ItemID.BIRDHOUSE_REDWOOD};
    enum Status {UNKNOWN,EMPTY,NEEDS_SEEDS,GROWING,READY}
    final String location,house;final Status status;final long remaining;final int item;
    private BirdhouseRun(String location,String house,Status status,long remaining,int item){
        this.location=location;this.house=house;this.status=status;this.remaining=remaining;this.item=item;
    }
    static BirdhouseRun unknown(int index){return new BirdhouseRun(LOCATIONS[index],"",Status.UNKNOWN,0,ITEMS[0]);}
    static BirdhouseRun read(int index,String raw,long now){
        if(raw==null)return unknown(index);String[] parts=raw.split(":",-1);if(parts.length!=2)return unknown(index);
        int varp;long seen;try{varp=Integer.parseInt(parts[0]);seen=Long.parseLong(parts[1]);}catch(NumberFormatException error){return unknown(index);}
        BirdHouseDecoder.State state=BirdHouseDecoder.getState(varp);if(seen<=0||state==BirdHouseDecoder.State.UNKNOWN)return unknown(index);
        if(state==BirdHouseDecoder.State.EMPTY)return new BirdhouseRun(LOCATIONS[index],"",Status.EMPTY,0,ITEMS[0]);
        String house=BirdHouseDecoder.getHouseName(varp);int item=ITEMS[(varp-1)/3];
        if(state==BirdHouseDecoder.State.BUILT)return new BirdhouseRun(LOCATIONS[index],house,Status.NEEDS_SEEDS,0,item);
        long remaining=Math.max(0,seen+DURATION-now);
        return new BirdhouseRun(LOCATIONS[index],house,remaining==0?Status.READY:Status.GROWING,remaining,item);
    }
    String label(){switch(status){case EMPTY:return "Empty";case NEEDS_SEEDS:return "Needs seeds";case GROWING:return "Growing";case READY:return "Estimated ready";default:return "Not checked";}}
    String time(){return remaining/60+"m "+remaining%60+"s left";}
    int progress(){return status==Status.READY?100:status==Status.GROWING?(int)Math.max(0,Math.min(100,(DURATION-remaining)*100/DURATION)):0;}
}

package lt.oneman.sync;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/** Four stable cards: updating observations never replaces the user's scrollable content. */
final class BirdhouseRunsPanel extends JPanel
{
    private final ItemManager items;
    private final java.util.List<HouseCard> houses=new ArrayList<>();
    private final JTextArea summary=CombatHubStyle.text("Log in to view your runs.");
    private final JTextArea hint=CombatHubStyle.text("Visit Fossil Island with Time Tracking enabled to detect birdhouses.");
    private final JLabel contract=CombatHubStyle.badge("Not checked",OneManCards.MUTED);
    BirdhouseRunsPanel(ItemManager items,Runnable refresh){
        super(new BorderLayout(0,6));this.items=items;setName("birdhouseRunsPanel");setOpaque(false);
        OneManCards content=new OneManCards();content.card(OneManCards.banner("Birdhouse runs","Fossil Island"));
        JPanel overview=CombatHubStyle.card(OneManCards.ACCENT,false);summary.setName("birdhouseSummary");overview.add(summary,BorderLayout.NORTH);overview.add(hint);content.card(overview);
        for(int i=0;i<4;i++){HouseCard card=new HouseCard(i);houses.add(card);content.card(card.card);}
        JPanel contractCard=CombatHubStyle.card(CombatHubStyle.GREEN,false);JLabel heading=new JLabel("Farming contract");heading.setForeground(Color.WHITE);heading.setFont(OneManCards.HEADING);
        contractCard.add(heading,BorderLayout.NORTH);contract.setName("farmingContractStatus");contractCard.add(contract);content.card(contractCard);content.finish();
        JScrollPane scroll=OneManCards.scroll(content);scroll.setName("birdhouseRunsScroll");scroll.getViewport().setBackground(new Color(24,29,26));add(scroll);
        JButton reload=new JButton("Refresh observations");reload.addActionListener(e->refresh.run());add(reload,BorderLayout.SOUTH);OneManCards.readable(this);
        loggedOut();
    }
    void loggedOut(){
        summary.setText("Log in to view your runs.");hint.setVisible(false);contract.setText("Not checked");contract.setForeground(OneManCards.MUTED);
        for(int i=0;i<4;i++)houses.get(i).update(BirdhouseRun.unknown(i),false);
    }
    void update(List<BirdhouseRun> runs,String contractState){
        long ready=runs.stream().filter(r->r.status==BirdhouseRun.Status.READY).count(),unknown=runs.stream().filter(r->r.status==BirdhouseRun.Status.UNKNOWN).count();
        summary.setText(unknown==4?"No observations yet":ready+" ready"+(unknown>0?" · "+unknown+" not checked":" · 4 locations"));hint.setVisible(unknown>0);
        contract.setText(contractState);contract.setForeground("Complete".equals(contractState)?CombatHubStyle.GREEN:OneManCards.MUTED);
        for(int i=0;i<4;i++)houses.get(i).update(runs.get(i),true);revalidate();
    }
    private final class HouseCard {
        final JPanel card=CombatHubStyle.card(OneManCards.ACCENT,false);
        final JLabel icon=new JLabel();final JLabel state=CombatHubStyle.badge("Not checked",OneManCards.MUTED);
        final JTextArea detail=CombatHubStyle.text("");final JProgressBar bar=CombatHubStyle.bar(100,0,OneManCards.ACCENT);
        int item=-1;
        HouseCard(int index){
            card.setName("birdhouseCard:"+index);JPanel header=new JPanel(new BorderLayout(6,0));header.setOpaque(false);
            icon.setPreferredSize(new Dimension(36,36));icon.setMinimumSize(new Dimension(36,36));icon.setHorizontalAlignment(SwingConstants.CENTER);icon.setIcon(CombatHubStyle.fallback());
            JTextArea location=CombatHubStyle.text(BirdhouseRun.LOCATIONS[index]);location.setForeground(Color.WHITE);location.setFont(OneManCards.HEADING);
            header.add(icon,BorderLayout.WEST);header.add(location);card.add(header,BorderLayout.NORTH);
            OneManCards body=new OneManCards();state.setName("birdhouseStatus:"+index);detail.setName("birdhouseDetail:"+index);body.card(state);body.card(detail);body.card(bar);card.add(body);
        }
        void update(BirdhouseRun run,boolean loggedIn){
            Color color=run.status==BirdhouseRun.Status.READY?CombatHubStyle.GREEN:run.status==BirdhouseRun.Status.UNKNOWN?OneManCards.MUTED:OneManCards.ACCENT;
            state.setText(loggedIn?run.label():"Log in");state.setForeground(color);
            detail.setText(run.status==BirdhouseRun.Status.GROWING?run.house+" · "+run.time():run.house);
            detail.setVisible(!detail.getText().isEmpty());bar.setValue(run.progress());bar.setForeground(color);bar.setVisible(run.status==BirdhouseRun.Status.GROWING||run.status==BirdhouseRun.Status.READY);
            if(item!=run.item){item=run.item;AsyncBufferedImage image=items==null?null:items.getImage(item);if(image!=null)image.addTo(icon);}
        }
    }
}

package lt.oneman.sync;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class ClueGroundOverlay extends Overlay
{
    @Inject private Client client;
    // Connected after injection completes; no Guice back-reference to the constructing hub.
    private volatile ClueHub hub;
    void setHub(ClueHub hub) { this.hub=hub; }
    @Inject private OneManSyncConfig config;
    ClueGroundOverlay() { setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.ABOVE_SCENE); }
    @Override public Dimension render(Graphics2D graphics)
    {
        ClueHub hub=this.hub;
        if (hub==null || !hub.enabled() || !config.clueGroundMarkers() || client.getGameState() != GameState.LOGGED_IN) return null;
        Map<Tile, Integer> rows = new HashMap<>();
        Map<Tile, Set<String>> names = new HashMap<>();
        FontMetrics metrics = graphics.getFontMetrics();
        for (ClueHub.GroundItem item : hub.groundItems())
        {
            Tile tile = item.tile;
            if (tile.getPlane() != client.getPlane() || tile.getItemLayer() == null) continue;
            if (!names.computeIfAbsent(tile, k -> new java.util.HashSet<>()).add(item.name)) continue;
            Set<ClueTier> tiers = hub.tiers(item.tags); if (tiers.isEmpty()) continue;
            String label = item.name + " [" + hub.kind(item.tags) + "]";
            int markerWidth = 0;
            for (ClueTier tier : tiers) markerWidth += 12 + metrics.stringWidth(tier.shortName);
            Point point = Perspective.getCanvasTextLocation(client, graphics, tile.getLocalLocation(), label,
                tile.getItemLayer().getHeight() + config.clueGroundLabelHeight());
            if (point == null) continue;
            int row = rows.getOrDefault(tile, 0); rows.put(tile, row + 1);
            int x = point.getX() - markerWidth / 2, y = point.getY() - row * (metrics.getHeight() + 2);
            graphics.setColor(Color.BLACK); graphics.drawString(label, x + 1, y + 1);
            graphics.setColor(new Color(235,235,220)); graphics.drawString(label, x, y);
            int dotX = x + metrics.stringWidth(label) + 5;
            for (ClueTier tier : tiers)
            {
                graphics.setColor(Color.BLACK); graphics.fillOval(dotX - 1, y - 8, 8, 8);
                graphics.setColor(tier.color); graphics.fillOval(dotX, y - 7, 6, 6);
                graphics.drawString(tier.shortName, dotX + 8, y); dotX += 12 + metrics.stringWidth(tier.shortName);
            }
        }
        return null;
    }
}

package lt.oneman.sync;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.LinkBrowser;

/** Local-only hub. All item definition and scene access stays on the client thread. */
@Singleton
final class ClueHub
{
    @Inject private Client client;
    @Inject private OneManMapLocations mapLocations;
    @Inject private ClientThread clientThread;
    @Inject private ItemManager items;
    @Inject private OneManSyncConfig config;
    @Inject private ConfigManager configs;
    @Inject private OverlayManager overlays;
    @Inject private ClueGroundOverlay groundOverlay;
    @Inject private ClueWidgetOverlay widgetOverlay;
    private ClueItemCatalog catalog;
    private StashRequirements stashRequirements;
    private volatile Map<String,List<StashRequirements.Row>> stashSnapshot=Collections.emptyMap();
    private boolean stashPending;
    private Panel panel;
    private volatile boolean active;
    private boolean scanPending;
    private String profile = "";
    private final ClueRewardCapture caskets = new ClueRewardCapture();
    private final Map<TileItem, GroundItem> ground = new IdentityHashMap<>();
    private final Map<Integer, Seen> recent = new LinkedHashMap<>();
    static final class GroundItem
    {
        final Tile tile;
        final String name;
        final ClueItemCatalog.Tags tags;
        GroundItem(Tile tile, String name, ClueItemCatalog.Tags tags) { this.tile = tile; this.name = name; this.tags = tags; }
    }
    private static final class Seen
    {
        final String name, origin;
        final int tick;
        final ClueItemCatalog.Tags tags;
        Seen(String name, String origin, ClueItemCatalog.Tags tags, int tick) { this.name = name; this.origin = origin; this.tags = tags; this.tick = tick; }
    }
    void startUp()
    {
        catalog = new ClueItemCatalog();
        stashRequirements=new StashRequirements();stashSnapshot=Collections.emptyMap();stashPending=true;
        groundOverlay.setHub(this); widgetOverlay.setHub(this);
        active = true; profile = ""; scanPending = true;
        ground.clear(); recent.clear(); overlays.add(groundOverlay); overlays.add(widgetOverlay);
    }
    void shutDown()
    {
        stashRequirements.clear();stashSnapshot=Collections.emptyMap();
        active = false; caskets.clear(); ground.clear(); recent.clear(); overlays.remove(groundOverlay); overlays.remove(widgetOverlay);
        groundOverlay.setHub(null); widgetOverlay.setHub(null);
        SwingUtilities.invokeLater(() -> panel = null);
    }
    JPanel companionPanel() { if (panel == null) panel = new Panel(); return panel; }
    boolean enabled() { return active && config.clueHubEnabled(); }
    Set<ClueTier> tiers(ClueItemCatalog.Tags tags) { return tags.visible(config.clueRequiredItems(), config.clueRewardItems(), config.clueCommonRewards()); }
    String kind(ClueItemCatalog.Tags tags) { return tags.kind(config.clueRequiredItems(), config.clueRewardItems(), config.clueCommonRewards()); }
    Collection<GroundItem> groundItems() { return ground.values(); }
    ClueItemCatalog.Tags classify(int id)
    {
        ItemComposition definition = items.getItemComposition(id);
        if (definition.getNote() != -1) { id = definition.getLinkedNoteId(); definition = items.getItemComposition(id); }
        if (definition.getPlaceholderTemplateId() != -1) { id = definition.getPlaceholderId(); definition = items.getItemComposition(id); }
        return catalog.classify(id, definition.getName());
    }
    void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();
        if(state==GameState.LOGGED_IN) stashPending=true;
        if(state==GameState.LOGIN_SCREEN) {stashRequirements.clear();publishStash(Collections.emptyMap());}
        if (state != GameState.LOGGED_IN) ground.clear();
        if (state == GameState.LOGGED_IN) scanPending = true;
        if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
        {
            recent.clear(); caskets.clear(); profile = ""; catalog.clearCache(); refresh();
        }
    }
    void onConfigChanged() { if (!active) return; caskets.clear(); ground.clear(); catalog.clearCache(); scanPending = true; refresh(); }
    void onGameTick()
    {
        if (!active || client.getGameState() != GameState.LOGGED_IN) return;
        String next = Objects.toString(configs.getRSProfileKey(), "");
        if (!next.equals(profile)) { profile = next; recent.clear(); caskets.clear(); ground.clear(); scanPending = true; refresh(); }
        if(stashPending) {stashPending=false;updateStash(false);}
        caskets.tick(client.getTickCount());
        // Once on enabling/login/region load; never scan the scene each tick or frame.
        if (enabled() && scanPending)
        {
            scanPending = false;
            for (Tile[][] plane : client.getScene().getTiles()) for (Tile[] column : plane) for (Tile tile : column)
                if (tile != null && tile.getGroundItems() != null) for (TileItem item : tile.getGroundItems()) track(tile, item, false);
        }
    }
    void onItemSpawned(ItemSpawned event) { if (enabled()) track(event.getTile(), event.getItem(), true); }
    void onItemDespawned(ItemDespawned event) { ground.remove(event.getItem()); }
    private void track(Tile tile, TileItem item, boolean record)
    {
        ClueItemCatalog.Tags tags = classify(item.getId());
        if (tiers(tags).isEmpty()) return;
        String name = items.getItemComposition(item.getId()).getName();
        ground.put(item, new GroundItem(tile, name, tags));
        if (record) remember(item.getId(), name, "Ground item seen (source unknown)", tags);
    }
    void onNpcLootReceived(net.runelite.client.events.NpcLootReceived event)
    {
        if (!enabled() || event.getNpc() == null) return;
        for (net.runelite.client.game.ItemStack item : event.getItems())
        {
            ClueItemCatalog.Tags tags = classify(item.getId());
            if (!tiers(tags).isEmpty()) remember(item.getId(), items.getItemComposition(item.getId()).getName(), "NPC drop: " + event.getNpc().getName(), tags);
        }
    }
    private void remember(int id, String name, String origin, ClueItemCatalog.Tags tags)
    {
        Seen previous = recent.get(id);
        if (previous != null && previous.tick == client.getTickCount() && origin.startsWith("Ground") && previous.origin.startsWith("NPC")) return;
        recent.remove(id); recent.put(id, new Seen(name, origin, tags, client.getTickCount()));
        while (recent.size() > 25) recent.remove(recent.keySet().iterator().next());
        refresh();
    }
    void onChatMessage(ChatMessage event)
    {
        if (!enabled() || (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM && event.getType() != ChatMessageType.MESBOX)) return;
        if (caskets.completion(net.runelite.client.util.Text.removeTags(event.getMessage()), client.getTickCount())) captureCasket();
    }
    private void updateStash(boolean bankChanged)
    {
        publishStash(stashRequirements.snapshot(client,Objects.toString(configs.getRSProfileKey(),""),bankChanged));
    }
    private void publishStash(Map<String,List<StashRequirements.Row>> snapshot)
    {
        stashSnapshot=snapshot;
        SwingUtilities.invokeLater(()-> {if(active && panel!=null) panel.stash.setRequirements(stashSnapshot);});
    }
    void onItemContainerChanged(ItemContainerChanged event)
    {
        if(active && (event.getContainerId()==net.runelite.api.gameval.InventoryID.BANK
            || event.getContainerId()==net.runelite.api.gameval.InventoryID.INV
            || event.getContainerId()==net.runelite.api.gameval.InventoryID.WORN))
            updateStash(event.getContainerId()==net.runelite.api.gameval.InventoryID.BANK);
        if (!enabled() || event.getContainerId() != net.runelite.api.gameval.InventoryID.TRAIL_REWARDINV) return;
        if (caskets.containerChanged(client.getTickCount())) captureCasket();
    }
    private void captureCasket()
    {
        ItemContainer container = client.getItemContainer(net.runelite.api.gameval.InventoryID.TRAIL_REWARDINV);
        if (container == null || caskets.tier() == null) return;
        ClueTier tier = caskets.tier();
        boolean found = false;
        for (Item item : container.getItems())
        {
            if (item.getId() < 0 || item.getQuantity() <= 0) continue;
            int id = items.canonicalize(item.getId());
            ClueItemCatalog.Tags base = classify(id);
            Set<ClueTier> reward = EnumSet.noneOf(ClueTier.class); reward.addAll(base.reward); reward.add(tier);
            remember(id, items.getItemComposition(id).getName(), "Opened " + tier.label + " casket (observed)",
                new ClueItemCatalog.Tags(base.required, reward, base.common, base.scroll));
            found = true;
        }
        if (found) caskets.consumed();
    }
    void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (!enabled() || !config.clueMenuMarkers()) return;
        MenuEntry entry = event.getMenuEntry(); int id = entry.getItemId(); MenuAction action = entry.getType();
        if (action == MenuAction.GROUND_ITEM_FIRST_OPTION || action == MenuAction.GROUND_ITEM_SECOND_OPTION
            || action == MenuAction.GROUND_ITEM_THIRD_OPTION || action == MenuAction.GROUND_ITEM_FOURTH_OPTION
            || action == MenuAction.GROUND_ITEM_FIFTH_OPTION || action == MenuAction.EXAMINE_ITEM_GROUND) id = entry.getIdentifier();
        else if (id < 0) return;
        if (id < 0 || entry.getTarget().contains("[Clue:")) return;
        ClueItemCatalog.Tags tags = classify(id); Set<ClueTier> tiers = tiers(tags); if (tiers.isEmpty()) return;
        StringBuilder suffix = new StringBuilder(" <col=aaaaaa>[Clue: " + kind(tags) + "</col>");
        for (ClueTier tier : tiers) suffix.append(" <col=").append(tier.hex()).append(">• ").append(tier.shortName).append("</col>");
        entry.setTarget(entry.getTarget() + suffix + "<col=aaaaaa>]</col>");
    }
    private void lookup(String query)
    {
        clientThread.invokeLater(() -> {
            if (!active) return;
            String result = "Enter an item name or item ID.";
            try
            {
                int id = Integer.parseInt(query.trim());
                if (id >= 0 && id < 100000) result = describe(items.getItemComposition(id).getName(), classify(id));
            }
            catch (NumberFormatException ignored)
            {
                List<net.runelite.http.api.item.ItemPrice> matches = new ArrayList<>(items.search(query.trim()));
                matches.sort(Comparator.comparing((net.runelite.http.api.item.ItemPrice item) -> !item.getName().equalsIgnoreCase(query.trim()))
                    .thenComparing(net.runelite.http.api.item.ItemPrice::getName));
                StringBuilder text = new StringBuilder(); int count = 0;
                for (net.runelite.http.api.item.ItemPrice item : matches)
                {
                    text.append(describe(item.getName(), classify(item.getId()))).append("\n\n");
                    if (++count >= 8) break;
                }
                result = count == 0 ? "No local name match. Try an item ID for untradeable items." : text.toString();
            }
            final String text = result;
            SwingUtilities.invokeLater(() -> { if (active && panel != null) panel.result.setText(text); });
        });
    }
    static String describe(String name, ClueItemCatalog.Tags tags)
    {
        StringBuilder text = new StringBuilder(name);
        if (tags.scroll != null) text.append("\nClue / casket: ").append(tags.scroll.label);
        if (!tags.required.isEmpty()) text.append("\nNeeded for emote / Charlie clues: ").append(labels(tags.required));
        if (!tags.reward.isEmpty()) text.append("\nReward table: ").append(labels(tags.reward));
        if (!tags.common.isEmpty()) text.append("\nCommon reward table: ").append(labels(tags.common));
        if (tags.scroll == null && tags.required.isEmpty() && tags.reward.isEmpty() && tags.common.isEmpty()) text.append("\nNo match in bundled clue catalogue.");
        return text.toString();
    }
    private static String labels(Set<ClueTier> tiers)
    {
        List<String> names = new ArrayList<>(); for (ClueTier tier : tiers) names.add(tier.label); return String.join(", ", names);
    }
    private void refresh()
    {
        List<Seen> snapshot = new ArrayList<>(recent.values()); Collections.reverse(snapshot); StringBuilder text = new StringBuilder();
        for (Seen seen : snapshot) text.append(describe(seen.name, seen.tags)).append("\n").append(seen.origin).append("\n\n");
        String value = text.length() == 0 ? "No clue-related drops observed in this session yet." : text.toString();
        SwingUtilities.invokeLater(() -> { if (active && panel != null) { panel.recent.setText(value); panel.status.setText(config.clueHubEnabled() ? "Clue Hub" : "Clue Hub — disabled"); } });
    }
    private final class Panel extends JPanel
    {
        final OneManMapPanel stash=new OneManMapPanel(mapLocations,OneManMapCatalog.Group.STASH);
        final JLabel status = new JLabel("Clue Hub");
        final JTextArea recent = area(), result = area();
        Panel()
        {
            setLayout(new BorderLayout(0, 8));
            recent.setText("No clue-related drops observed in this session yet.");
            JPanel header = new JPanel(new BorderLayout(0,6));header.setBackground(new Color(36,53,44));header.setBorder(BorderFactory.createEmptyBorder(8,8,8,8));header.add(status, BorderLayout.NORTH);
            JPanel legend = new JPanel(new GridLayout(3, 2, 8, 5));
            for (ClueTier tier : ClueTier.values()) { JLabel label = CombatHubStyle.badge(tier.label,tier.color); label.setForeground(tier.color); label.setFont(OneManCards.HEADING); label.setToolTipText(tier.label); legend.add(label); }
