package lt.oneman.sync;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.cluescrolls.clues.EmoteClue;
import net.runelite.client.plugins.cluescrolls.clues.item.ItemRequirement;

/** Offline classification; membership never proves the actual origin of a particular item. */
final class ClueItemCatalog
{
    static final class Tags
    {
        final Set<ClueTier> required, reward, common;
        final ClueTier scroll;
        Tags(Set<ClueTier> required, Set<ClueTier> reward, Set<ClueTier> common, ClueTier scroll)
        {
            this.required = Collections.unmodifiableSet(required); this.reward = Collections.unmodifiableSet(reward);
            this.common = Collections.unmodifiableSet(common); this.scroll = scroll;
        }
        Set<ClueTier> visible(boolean requirements, boolean rewards, boolean commons)
        {
            Set<ClueTier> result = EnumSet.noneOf(ClueTier.class);
            if (scroll != null) result.add(scroll);
            if (requirements) result.addAll(required);
            if (rewards) { result.addAll(reward); if (commons) result.addAll(common); }
            return result;
        }
        String kind(boolean requirements, boolean rewards, boolean commons)
        {
            if (scroll != null) return "Clue";
            boolean req = requirements && !required.isEmpty();
            boolean rew = rewards && (!reward.isEmpty() || (commons && !common.isEmpty()));
            return req && rew ? "Req / reward" : req ? "Req" : "Reward table";
        }
    }
    private static final class Requirement
    {
        final ClueTier tier;
        final ItemRequirement item;
        Requirement(ClueTier tier, ItemRequirement item) { this.tier = tier; this.item = item; }
    }
    private final List<Requirement> requirements = new ArrayList<>();
    private final Map<String, Set<ClueTier>> rewards = new HashMap<>(), commons = new HashMap<>();
    private final Map<Integer, Tags> cache = new HashMap<>();
    private int unresolvedSteps;
    ClueItemCatalog()
    {
        for (String line : lines("clue-emote-steps.tsv"))
        {
            String[] parts = line.split("\t", 2);
            EmoteClue clue = EmoteClue.forText(parts[1]);
            if (clue == null) { unresolvedSteps++; continue; }
            for (ItemRequirement requirement : clue.getItemRequirements()) requirements.add(new Requirement(ClueTier.valueOf(parts[0]), requirement));
        }
        for (String line : lines("clue-rewards.tsv"))
        {
            String[] parts = line.split("\t", 3);
            Map<String, Set<ClueTier>> target = parts[1].equals("COMMON") ? commons : rewards;
            target.computeIfAbsent(normal(parts[2]), key -> EnumSet.noneOf(ClueTier.class)).add(ClueTier.valueOf(parts[0]));
        }
    }
    int unresolvedSteps() { return unresolvedSteps; }
    void clearCache() { cache.clear(); }
    Tags classify(int id, String name)
    {
        Tags existing = cache.get(id);
        if (existing != null) return existing;
        Set<ClueTier> req = EnumSet.noneOf(ClueTier.class);
        for (Requirement requirement : requirements) if (requirement.item.fulfilledBy(id)) req.add(requirement.tier);
        // Charlie tasks are separate from emotes. Marking the item does not imply the gathering task is complete.
        switch (id)
        {
            case ItemID.PIKE: case ItemID.TROUT: case ItemID.LEATHER_ARMOUR: case ItemID.LEATHER_CHAPS:
            case ItemID.RAW_HERRING: case ItemID.RAW_TROUT: case ItemID.IRON_ORE: case ItemID.IRON_DAGGER:
                req.add(ClueTier.BEGINNER); break;
            default: break;
        }
        Tags tags = new Tags(req, rewardTiers(name, false), rewardTiers(name, true), ClueTier.scrollTier(name));
        if (cache.size() >= 4096) cache.clear();
        cache.put(id, tags); return tags;
    }
    Set<ClueTier> rewardTiers(String name, boolean common)
    {
        Set<ClueTier> result = EnumSet.noneOf(ClueTier.class);
        result.addAll((common ? commons : rewards).getOrDefault(normal(name), Collections.emptySet())); return result;
    }
    static String normal(String name) { return name.replace('\u00a0', ' ').replace('\u2019', '\'').trim().toLowerCase(Locale.ROOT); }
    private static List<String> lines(String file)
    {
        List<String> lines = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            Objects.requireNonNull(ClueItemCatalog.class.getResourceAsStream(file), file), StandardCharsets.UTF_8)))
        {
            String line;
            while ((line = reader.readLine()) != null) if (!line.isEmpty() && !line.startsWith("#")) lines.add(line);
            return lines;
        }
        catch (IOException error) { throw new IllegalStateException("Cannot read bundled clue data", error); }
    }
}

package lt.oneman.sync;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Correlates server clue completion with a fresh reward container in either event order. */
final class ClueRewardCapture
{
    private static final Pattern COMPLETED = Pattern.compile("You have completed ([0-9,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.", Pattern.CASE_INSENSITIVE);
    private ClueTier pending;
    private int deadline, version, consumed, changedTick = -1;
    private String last = "";
    void clear() { pending = null; deadline = version = consumed = 0; changedTick = -1; last = ""; }
    boolean completion(String message, int tick)
    {
        Matcher match = COMPLETED.matcher(message);
        if (!match.find()) return false;
        String token = match.group(2).toLowerCase(Locale.ROOT) + ":" + match.group(1);
        if (token.equals(last)) return false;
        last = token; pending = ClueTier.valueOf(match.group(2).toUpperCase(Locale.ROOT)); deadline = tick + 5;
        return changedTick == tick && version > consumed;
    }
    boolean containerChanged(int tick)
    {
        version++; changedTick = tick;
        return pending != null && tick <= deadline;
    }
    ClueTier tier() { return pending; }
    void consumed() { consumed = version; pending = null; }
    void tick(int tick) { if (tick > deadline) pending = null; }
}

package lt.oneman.sync;

import java.awt.Color;
import java.util.Locale;

enum ClueTier
{
    BEGINNER("Beginner", "B", 0xaaaaaa), EASY("Easy", "E", 0x66cc66),
    MEDIUM("Medium", "M", 0x66aaff), HARD("Hard", "H", 0xff6666),
    ELITE("Elite", "El", 0xcc88ff), MASTER("Master", "Ma", 0xffcc55);

    final String label, shortName;
    final Color color;
    ClueTier(String label, String shortName, int rgb)
    {
        this.label = label; this.shortName = shortName; this.color = new Color(rgb);
    }
    String hex() { return String.format("%06x", color.getRGB() & 0xffffff); }
    static ClueTier scrollTier(String name)
    {
        String n = name.toLowerCase(Locale.ROOT);
        if (!(n.startsWith("clue scroll (") || n.startsWith("reward casket (")
            || n.startsWith("clue nest (") || n.startsWith("clue bottle (") || n.startsWith("clue geode ("))) return null;
        for (ClueTier tier : values()) if (n.contains("(" + tier.label.toLowerCase(Locale.ROOT) + ")")) return tier;
        return null;
    }
}

package lt.oneman.sync;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

final class ClueWidgetOverlay extends WidgetItemOverlay
{
    // Connected after injection completes; no Guice back-reference to the constructing hub.
    private volatile ClueHub hub;
    void setHub(ClueHub hub) { this.hub=hub; }
    @Inject private OneManSyncConfig config;
    ClueWidgetOverlay() { showOnInventory(); showOnBank(); showOnEquipment(); }
    @Override public void renderItemOverlay(Graphics2D graphics, int id, WidgetItem item)
    {
        ClueHub hub=this.hub;
        if (hub==null || id < 0 || !hub.enabled() || !config.clueWidgetMarkers()) return;
        Set<ClueTier> tiers = hub.tiers(hub.classify(id));
        Rectangle bounds = item.getCanvasBounds(); int x = bounds.x + bounds.width - 7;
        for (ClueTier tier : tiers)
        {
            graphics.setColor(Color.BLACK); graphics.fillOval(x - 1, bounds.y + bounds.height - 8, 8, 8);
            graphics.setColor(tier.color); graphics.fillOval(x, bounds.y + bounds.height - 7, 6, 6); x -= 6;
        }
    }
}

package lt.oneman.sync;

import java.awt.Color;
import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.client.util.Text;

/** Immutable game-cache catalogue. Read on the client thread; never downloads task data. */
final class CombatAchievementCatalog
{
    // These enum/struct parameters have no named RuneLite gameval constants.
    // Cache mapping independently checked against jimmyununu/combat-achievement-lookup.
    static final int BOSS_NAMES=3971, TASK_ID=1306, NAME=1308, DESCRIPTION=1309, TYPE=1311, BOSS=1312;
    enum Tier {
        EASY("Easy",3981,0x86cf97), MEDIUM("Medium",3982,0x83bdec), HARD("Hard",3983,0xec9292),
        ELITE("Elite",3984,0xc59be7), MASTER("Master",3985,0xe7b47c), GRANDMASTER("Grandmaster",3986,0xe7c65d);
        final String label;final int enumId;final Color color;
        Tier(String label,int enumId,int rgb){this.label=label;this.enumId=enumId;this.color=new Color(rgb);}
        int points(){return ordinal()+1;}
        @Override public String toString(){return label;}
    }
    static final class Task {
        final int id;final String name,description,boss,type;final Tier tier;
        Task(int id,String name,String description,String boss,String type,Tier tier){
            this.id=id;this.name=name;this.description=description;this.boss=boss;this.type=type;this.tier=tier;
        }
    }
    static String type(int value){
        String[] names={"Other","Stamina","Perfection","Kill Count","Mechanical","Restriction","Speed"};
        return value>0&&value<names.length?names[value]:names[0];
    }
    static List<Task> load(Client client) {
        EnumComposition bosses=client.getEnum(BOSS_NAMES);
        if(bosses==null)return Collections.emptyList();
        List<Task> tasks=new ArrayList<>();Set<Integer> ids=new HashSet<>();
        for(Tier tier:Tier.values()) {
            EnumComposition entries=client.getEnum(tier.enumId);
            if(entries==null||entries.getIntVals()==null||entries.getIntVals().length==0)return Collections.emptyList();
            for(int structId:entries.getIntVals()) {
                StructComposition value=client.getStructComposition(structId);
                if(value==null)return Collections.emptyList();
                int id=value.getIntValue(TASK_ID);String name=clean(value.getStringValue(NAME));
                if(id<0||name.isEmpty()||!ids.add(id))return Collections.emptyList();
                String boss=clean(bosses.getStringValue(value.getIntValue(BOSS)));
                if(boss.isEmpty()||"None".equalsIgnoreCase(boss)||"null".equalsIgnoreCase(boss))boss="General";
                tasks.add(new Task(id,name,clean(value.getStringValue(DESCRIPTION)),boss,type(value.getIntValue(TYPE)),tier));
            }
        }
        tasks.sort(Comparator.comparing((Task t)->t.boss,String.CASE_INSENSITIVE_ORDER).thenComparingInt(t->t.tier.ordinal()).thenComparing(t->t.name));
        return Collections.unmodifiableList(tasks);
    }
    private static String clean(String value){return value==null?"":Text.removeTags(value.replace("<br>"," ")).trim();}
    static boolean completed(int id,int[] packed){return id>=0&&id/32<packed.length&&(packed[id/32]&(1<<(id%32)))!=0;}
}

package lt.oneman.sync;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.lang.ref.WeakReference;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import net.runelite.api.SpriteID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;

/** Local game portraits only. No Wiki downloads, account data or network requests. */
@Singleton
final class CombatAchievementIcons
{
    @Inject private SpriteManager sprites;
    @Inject private ItemManager items;
    private final Map<String,Icon> cached=new HashMap<>();
    private final Map<String,List<WeakReference<JLabel>>> waiting=new HashMap<>();
    private boolean active;
    private int generation;
    void startUp(){SwingUtilities.invokeLater(()->{active=true;generation++;});}
    void shutDown(){SwingUtilities.invokeLater(()->{active=false;generation++;waiting.clear();cached.clear();});}
    void addTo(String boss,JLabel label){
        label.setIcon(CombatHubStyle.fallback());label.setPreferredSize(new Dimension(40,38));label.setMinimumSize(new Dimension(40,38));
        label.setHorizontalAlignment(SwingConstants.CENTER);label.setToolTipText(boss);
        if(!active)return;
        String key=normal(boss);Icon known=cached.get(key);if(known!=null){label.setIcon(known);return;}
        int item=item(key);
        if(item>=0){AsyncBufferedImage image=items.getImage(item);if(image!=null)image.addTo(label);return;}
        int sprite=sprite(key);
        if(sprite<0){
            // A real category icon for future/unrecognised groups, rather than an empty portrait.
            AsyncBufferedImage image=items.getImage(ItemID.CA_BOOK);if(image!=null)image.addTo(label);return;
        }
        // Weak references avoid retaining detached cards while a cache sprite is loading.
        if(waiting.containsKey(key)){waiting.get(key).add(new WeakReference<>(label));return;}
        waiting.put(key,new ArrayList<>(Collections.singletonList(new WeakReference<>(label))));int requested=generation;
        sprites.getSpriteAsync(sprite,0,image->SwingUtilities.invokeLater(()->{
            if(!active||generation!=requested)return;
            List<WeakReference<JLabel>> labels=waiting.remove(key);if(image==null||labels==null)return;
            double factor=Math.min(32d/image.getWidth(),32d/image.getHeight());
            int w=Math.max(1,(int)Math.round(image.getWidth()*factor)),h=Math.max(1,(int)Math.round(image.getHeight()*factor));
            BufferedImage portrait=new BufferedImage(36,36,BufferedImage.TYPE_INT_ARGB);Graphics2D g=portrait.createGraphics();
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BILINEAR);g.drawImage(image,(36-w)/2,(36-h)/2,w,h,null);g.dispose();
            Icon icon=new ImageIcon(portrait);cached.put(key,icon);for(WeakReference<JLabel> ref:labels){JLabel target=ref.get();if(target!=null)target.setIcon(icon);}
        }));
    }
    private static String normal(String boss){return boss.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}
    static int item(String key){switch(normal(key)){
