        void showLoggedOut() { runs.loggedOut();patches.setStatuses(Collections.emptyMap()); }
        void showStatus(List<BirdhouseRun> observations,String contract,Map<String,String> observed) {
            runs.update(observations,contract);
            Map<String,String> status=new HashMap<>();
            observed.forEach((key,value)->status.put(key.replace(": ",":"),value));
            patches.setStatuses(status);
        }
    }

    public static class TrackedPatchDef {
        private final String name;
        private final int regionId;
        private final int varbitId;
        private final FarmingPatchType implementation;

        public TrackedPatchDef(String name, int regionId, int varbitId, FarmingPatchType implementation) {
            this.name = name;
            this.regionId = regionId;
            this.varbitId = varbitId;
            this.implementation = implementation;
        }

        public String getName() {
            return this.name;
        }

        public int getRegionId() {
            return this.regionId;
        }

        public int getVarbitId() {
            return this.varbitId;
        }

        public FarmingPatchType getImplementation() {
            return this.implementation;
        }

        public String configKey() {
            return this.regionId + "." + this.varbitId;
        }
    }
}

package lt.oneman.sync;

import java.util.*;
import java.util.stream.Collectors;
import net.runelite.client.plugins.timetracking.farming.Produce;

/** Crop-to-patch types come from the installed RuneLite catalogue, never guessed from a substring. */
final class FarmingSeedCatalog
{
    static final class Seed
    {
        final String name,category,note;
        final Produce produce;
        final List<String> aliases;
        Seed(Produce produce,String name,String category,String note,String... extra)
        {
            this.produce=produce;this.name=name;this.category=category;this.note=note;
            List<String> aliases=new ArrayList<>(Arrays.asList(extra));aliases.add(name);aliases.add(produce.getName());
            this.aliases=aliases.stream().map(FarmingSeedCatalog::normal).distinct().collect(Collectors.toList());
        }
    }
    private static final Set<String> POTTED=new HashSet<>(Arrays.asList("TREE","FRUIT_TREE","HARDWOOD_TREE","CALQUAT","SPIRIT_TREE","CELASTRUS","REDWOOD"));
    private final List<Seed> seeds=new ArrayList<>();
    FarmingSeedCatalog()
    {
        for(Produce produce:Produce.values()) {
            if(produce.getPatchImplementation()==null || produce.name().equals("ANYHERB")) continue;
            String type=produce.getPatchImplementation().name();
            if(type.equals("COMPOST")||type.equals("BIG_COMPOST")) continue;
            String name=produce.getName()+(type.equals("FRUIT_TREE")&&!produce.name().equals("PINEAPPLE")?" tree seed":" seed");
            switch(produce.name()) {
                case "OAK":name="Acorn";break;
                case "SEAWEED":name="Seaweed spore";break;
                case "MUSHROOM":name="Mushroom spore";break;
                case "GOUTWEED":name="Gout tuber";break;
                case "SPIRIT_TREE":name="Spirit seed";break;
                case "CALQUAT":name="Calquat tree seed";break;
                case "REDWOOD":name="Redwood tree seed";break;
                case "CRYSTAL_TREE":name="Crystal acorn";break;
                case "ELKHORN_CORAL":name="Elkhorn coral fragment";break;
                case "PILLAR_CORAL":name="Pillar coral fragment";break;
                case "UMBRAL_CORAL":name="Umbral coral fragment";break;
                default:break;
            }
            String category=category(type);
            String note=POTTED.contains(type)?"Grow the seed in a filled plant pot and water it. Plant the resulting sapling in a "+category+" patch.":"Plant this material in a "+category+" patch. Check the Farming level and access requirements.";
            String sapling=POTTED.contains(type)?produce.getName()+" sapling":"";
            String extra=produce.name().equals("MUSHROOM")?"Bittercap mushroom spore":produce.name().equals("BELLADONNA")?"Nightshade":"";
            seeds.add(new Seed(produce,name,category,note,sapling,extra));
        }
        seeds.sort(Comparator.comparing(s->s.name));
    }
    List<Seed> search(String query)
    {
        String q=normal(query);if(q.isEmpty()) return Collections.emptyList();
        String[] words=q.split(" ");
        return seeds.stream().filter(seed->seed.aliases.stream().anyMatch(alias->Arrays.stream(words).allMatch(alias::contains)))
            .sorted(Comparator.<Seed>comparingInt(seed->seed.aliases.contains(q)?0:1).thenComparing(seed->seed.name)).collect(Collectors.toList());
    }
    static String category(String implementation)
    {
        switch(implementation) {
            case "HARDWOOD_TREE":return "Hardwood";
            case "FRUIT_TREE":return "Fruit Tree";
            case "SPIRIT_TREE":return "Spirit Tree";
            case "CRYSTAL_TREE":return "Crystal Tree";
            default:return implementation.charAt(0)+implementation.substring(1).toLowerCase(Locale.ROOT);
        }
    }
    static String normal(String text)
    {
        return text.toLowerCase(Locale.ROOT).replaceAll("\\b(seeds?|saplings?|tree)\\b", " ").replaceAll("[^a-z0-9]+"," ").trim();
    }
}

package lt.oneman.sync;

import java.awt.*;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

final class FarmingSeedPanel extends JPanel
{
    private final FarmingSeedCatalog catalog=new FarmingSeedCatalog();
    private final OneManMapLocations maps;
    private final Consumer<String> browse;
    private final JTextField query=new JTextField();
    private final OneManCards results=new OneManCards();
    FarmingSeedPanel(OneManMapLocations maps,Consumer<String> browse)
    {
        super(new BorderLayout(0,6));this.maps=maps;this.browse=browse;
        JPanel header=new JPanel(new BorderLayout(0,6));
        header.add(OneManCards.banner("Seed finder", "Find where a seed, sapling, spore or tuber belongs."),BorderLayout.NORTH);
        query.setName("farmingSeedSearch");query.putClientProperty("JTextField.placeholderText","e.g. ranarr seed");query.setToolTipText("Try ranarr seed, acorn, jute seed or maple sapling");
        JPanel row=new JPanel(new BorderLayout(6,0));JLabel label=new JLabel("Seed");label.setForeground(OneManCards.ACCENT);row.add(label,BorderLayout.WEST);row.add(query,BorderLayout.CENTER);
        header.add(row,BorderLayout.SOUTH);add(header,BorderLayout.NORTH);add(OneManCards.scroll(results),BorderLayout.CENTER);
        query.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent event) {search();}
            public void removeUpdate(DocumentEvent event) {search();}
            public void changedUpdate(DocumentEvent event) {search();}
        });search();OneManTheme.apply(this);
    }
    private void search()
    {
        results.removeAll();List<FarmingSeedCatalog.Seed> matches=catalog.search(query.getText());
        if(matches.isEmpty()) results.card(OneManCards.text(query.getText().trim().isEmpty()?"Type a name, for example ranarr seed or acorn.":"No known planting match. Check the exact name; this may be a non-Farming item."));
        for(FarmingSeedCatalog.Seed seed:matches) {
            JPanel card=OneManCards.card();card.setName("seedResult:"+seed.produce.name());
            JPanel title=new JPanel(new BorderLayout(6,0));title.setOpaque(false);
            JLabel icon=new JLabel();icon.setPreferredSize(new Dimension(32,34));maps.cropIcon(icon,seed.produce);title.add(icon,BorderLayout.WEST);
            JTextArea name=OneManCards.text(seed.name);name.setForeground(Color.WHITE);name.setFont(new Font(Font.SANS_SERIF,Font.BOLD,13));title.add(name,BorderLayout.CENTER);card.add(title,BorderLayout.NORTH);
            JTextArea note=OneManCards.text("Patch: "+seed.category+"\n"+seed.note);card.add(note,BorderLayout.CENTER);
            JButton locations=new JButton("Show "+seed.category+" patches");locations.setName("seedBrowse:"+seed.produce.name());locations.addActionListener(event->browse.accept(seed.category));card.add(locations,BorderLayout.SOUTH);results.card(card);
        }
        results.finish();
    }
}

