package lt.oneman.sync;

import java.awt.Color;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.emote.STASHUnit;

/** Offline static sites, independent of account unlocks and crop observations. */
final class OneManMapCatalog
{
    enum Group { STASH, FARMING }
    static final class Site
    {
        final String id, category, name;
        final List<WorldPoint> points;
        final Color color;
        Site(String id, String category, String name, Color color, WorldPoint... points)
        {
            this.id=id; this.category=category; this.name=name; this.color=color;
            this.points=Collections.unmodifiableList(Arrays.asList(points.clone()));
        }
        @Override public String toString() { return name; }
    }
    static List<Site> stashes()
    {
        Map<String, ClueTier> tiers=new HashMap<>();
        for(String[] row:rows("stash-tiers.tsv")) tiers.put(row[0],ClueTier.valueOf(row[1]));
        List<Site> sites=new ArrayList<>();
        for(STASHUnit unit:STASHUnit.values()) {
            ClueTier tier=tiers.get(unit.name());
            if(tier!=null) sites.add(new Site(unit.name(),tier.label,pretty(unit.name()),tier.color,unit.getWorldPoints()));
        }
        sites.sort(Comparator.comparing(s->s.name)); return Collections.unmodifiableList(sites);
    }
    static List<Site> farming()
    {
        List<Site> sites=new ArrayList<>();
        for(String[] row:rows("farming-locations.tsv")) {
            String category=row[0];
            Color color=category.equals("Tree")?new Color(85,190,105):category.equals("Herb")?new Color(85,205,170):new Color(170,205,80);
            sites.add(new Site(category+":"+row[1],category,row[1],color,
                new WorldPoint(Integer.parseInt(row[2]),Integer.parseInt(row[3]),Integer.parseInt(row[4]))));
        }
        return Collections.unmodifiableList(sites);
    }
    static List<Site> filter(List<Site> sites, String category)
    {
        if("All".equals(category)) return sites;
        List<Site> result=new ArrayList<>();
        for(Site site:sites) if(site.category.equals(category)) result.add(site);
        return Collections.unmodifiableList(result);
    }
    private static List<String[]> rows(String file)
    {
        List<String[]> rows=new ArrayList<>();
        try(BufferedReader reader=new BufferedReader(new InputStreamReader(
            Objects.requireNonNull(OneManMapCatalog.class.getResourceAsStream(file)),StandardCharsets.UTF_8))) {
            String line;
            while((line=reader.readLine())!=null) if(!line.startsWith("#")&&!line.trim().isEmpty()) rows.add(line.split("\t"));
        } catch(IOException error) { throw new IllegalStateException("Cannot load map catalogue "+file,error); }
        return rows;
    }
    private static String pretty(String name)
    {
        StringBuilder result=new StringBuilder();
        for(String word:name.replaceFirst("_\\d+$", "").replaceFirst("^_", "").toLowerCase(Locale.ROOT).split("_")) {
            if(result.length()>0) result.append(' ');
            if(!word.isEmpty()) result.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
        }
        return result.toString();
    }
}

package lt.oneman.sync;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/** Owns only OneMan's location pins. UI changes are scheduled onto the client thread. */
@Singleton
final class OneManMapLocations
{
    @Inject private Client client;
    @Inject private net.runelite.client.game.ItemManager items;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configs;
    @Inject private WorldMapPointManager manager;
    private volatile boolean active;
    private final Map<OneManMapCatalog.Group,List<WorldMapPoint>> pins=new EnumMap<>(OneManMapCatalog.Group.class);
    private final Map<OneManMapCatalog.Group,List<OneManMapCatalog.Site>> catalog=new EnumMap<>(OneManMapCatalog.Group.class);
    private final Map<OneManMapCatalog.Group,String> categories=new java.util.concurrent.ConcurrentHashMap<>();
    private final Map<OneManMapCatalog.Group,Boolean> visible=new java.util.concurrent.ConcurrentHashMap<>();
    private volatile List<OneManMapCatalog.Site> minimapStashes=Collections.emptyList();
    private WorldPoint pendingFocus;
    private String selected="";

    synchronized void startUp()
    {
        catalog.put(OneManMapCatalog.Group.STASH,OneManMapCatalog.stashes());
        catalog.put(OneManMapCatalog.Group.FARMING,OneManMapCatalog.farming());
        for(OneManMapCatalog.Group group:OneManMapCatalog.Group.values()) {
            String category=configs.getConfiguration("one-man-sync",key(group,"Filter"));
            if(category==null || !categories(group).contains(category)) category=group==OneManMapCatalog.Group.STASH?"All":"Tree";
            categories.put(group,category);
            visible.put(group,!"false".equals(configs.getConfiguration("one-man-sync",key(group,"Pins"))));
        }
        selected=""; pendingFocus=null; active=true;
        clientThread.invokeLater(() -> { if(active) for(OneManMapCatalog.Group group:OneManMapCatalog.Group.values()) rebuild(group); });
    }
    synchronized void shutDown()
    {
        active=false; pendingFocus=null; minimapStashes=Collections.emptyList();
        for(OneManMapCatalog.Group group:OneManMapCatalog.Group.values()) clear(group);
    }
    List<String> categories(OneManMapCatalog.Group group)
    {
        List<String> result=new ArrayList<>();result.add("All");
        if(group==OneManMapCatalog.Group.STASH) for(ClueTier tier:ClueTier.values()) result.add(tier.label);
        else { Set<String> names=new TreeSet<>(); for(OneManMapCatalog.Site site:catalog.get(group)) names.add(site.category); result.addAll(names); }
        return result;
    }
    String category(OneManMapCatalog.Group group) { return categories.get(group); }
    boolean visible(OneManMapCatalog.Group group) { return Boolean.TRUE.equals(visible.get(group)); }
    List<OneManMapCatalog.Site> sites(OneManMapCatalog.Group group,String filter) { return OneManMapCatalog.filter(catalog.get(group),filter); }
    void icon(javax.swing.JLabel label,String category)
    {
        for(net.runelite.client.plugins.timetracking.farming.Produce produce:net.runelite.client.plugins.timetracking.farming.Produce.values()) {
            if(produce.getPatchImplementation()!=null && FarmingSeedCatalog.category(produce.getPatchImplementation().name()).equals(category)) {
                cropIcon(label,produce);return;
            }
        }
        Color color=new Color(180,195,125);
        for(ClueTier tier:ClueTier.values()) if(tier.label.equals(category)) color=tier.color;
        label.setIcon(new javax.swing.ImageIcon(icon(color,"S",false)));
    }
    void cropIcon(javax.swing.JLabel label,net.runelite.client.plugins.timetracking.farming.Produce produce)
    {
        net.runelite.client.util.AsyncBufferedImage image=items.getImage(produce.getItemID());
        if(image!=null) image.addTo(label);else label.setIcon(new javax.swing.ImageIcon(icon(new Color(120,185,105),"F",false)));
    }
    List<OneManMapCatalog.Site> minimapStashes() { return minimapStashes; }
    void configure(OneManMapCatalog.Group group,String category,boolean show)
    {
        clientThread.invokeLater(() -> {
            if(!active || !categories(group).contains(category)) return;
            categories.put(group,category); visible.put(group,show); selected="";pendingFocus=null;
            configs.setConfiguration("one-man-sync",key(group,"Filter"),category);
            configs.setConfiguration("one-man-sync",key(group,"Pins"),show);
            rebuild(group);
        });
    }
    void focus(OneManMapCatalog.Group group,OneManMapCatalog.Site site)
    {
        clientThread.invokeLater(() -> {
            if(!active || !sites(group,categories.get(group)).contains(site)) return;
            selected=site.id; pendingFocus=site.points.get(0); rebuild(group); tick();
        });
    }
    void tick()
    {
        WorldPoint target=pendingFocus;
        if(!active || target==null || client.getGameState()!=GameState.LOGGED_IN) return;
        Widget map=client.getWidget(InterfaceID.Worldmap.MAP_DISPLAY);
        if(map==null || map.isHidden() || client.getWorldMap()==null) return;
        if(active) client.getWorldMap().setWorldMapPositionTarget(target);
        if(pendingFocus==target) pendingFocus=null;
    }
    private static String key(OneManMapCatalog.Group group,String suffix) { return "map"+(group==OneManMapCatalog.Group.STASH?"Stash":"Farming")+suffix; }
    private synchronized void clear(OneManMapCatalog.Group group)
    {
        List<WorldMapPoint> old=pins.remove(group); if(old!=null) for(WorldMapPoint point:old) manager.remove(point);
    }
    private synchronized void rebuild(OneManMapCatalog.Group group)
    {
        if(!active) return;
        clear(group);
        List<OneManMapCatalog.Site> sites=visible(group)?sites(group,categories.get(group)):Collections.emptyList();
        if(group==OneManMapCatalog.Group.STASH) minimapStashes=sites;
        List<WorldMapPoint> points=new ArrayList<>();
        for(OneManMapCatalog.Site site:sites) for(WorldPoint location:site.points) {
            WorldMapPoint point=new WorldMapPoint(location,icon(site.color,group==OneManMapCatalog.Group.STASH?"S":"F",site.id.equals(selected)));
            point.setImagePoint(new net.runelite.api.Point(11,25));
            point.setName("OneMan "+site.category+": "+site.name);
            point.setTooltip(tooltip(group,site,location.getPlane()));
            point.setJumpOnClick(false);point.setSnapToEdge(site.id.equals(selected));points.add(point);manager.add(point);
        }
        pins.put(group,points);
    }
    static String tooltip(OneManMapCatalog.Group group,OneManMapCatalog.Site site,int plane)
    {
        StringBuilder text=new StringBuilder(group==OneManMapCatalog.Group.STASH?"STASH | ":"Farming | ").append(site.category).append("<br>");
        int line=0;
        for(String word:site.name.split(" ")) {
            if(line>0 && line+word.length()+1>32) {text.append("<br>");line=0;}
            if(line>0) {text.append(' ');line++;}
            text.append(word);line+=word.length();
        }
        if(plane>0) text.append("<br>Floor ").append(plane);
        return text.toString();
    }
    private static BufferedImage icon(Color color,String letter,boolean selected)
    {
        BufferedImage image=new BufferedImage(22,26,BufferedImage.TYPE_INT_ARGB); Graphics2D g=image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(20,25,30,240));g.fillOval(1,1,20,20);
        g.setColor(color);g.setStroke(new BasicStroke(selected?3:2));g.drawOval(2,2,18,18);g.fillPolygon(new int[]{6,16,11},new int[]{18,18,25},3);
        g.setFont(new Font(Font.SANS_SERIF,Font.BOLD,12));g.drawString(letter,7,15);g.dispose();return image;
    }
}

package lt.oneman.sync;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/** Shared category cards: an icon, location count and explicit location selector. */
final class OneManMapPanel extends JPanel
{
    private final OneManMapLocations maps;
    private final OneManMapCatalog.Group group;
    private final JComboBox<String> filter;
    private final JCheckBox show;
    private final JTextField search=new JTextField();
    private final OneManCards cards=new OneManCards();
    private final JLabel count=new JLabel();
    private final Map<String,String> selected=new HashMap<>();
    private final Map<String,JComboBox<OneManMapCatalog.Site>> selectors=new HashMap<>();
    private final Map<String,JTextArea> descriptions=new HashMap<>();
    private Map<String,List<StashRequirements.Row>> requirements=Collections.emptyMap();
    private final Map<String,OneManCards> requirementPanels=new HashMap<>();
    private Map<String,String> statuses=Collections.emptyMap();

    OneManMapPanel(OneManMapLocations maps,OneManMapCatalog.Group group)
    {
        super(new BorderLayout(0,6));this.maps=maps;this.group=group;
        boolean farming=group==OneManMapCatalog.Group.FARMING;
        filter=new JComboBox<>(maps.categories(group).toArray(new String[0]));
        filter.setName(farming?"farmingTypeFilter":"stashTierFilter");filter.setSelectedItem(maps.category(group));
        filter.setMinimumSize(new Dimension(0,24));
        show=new JCheckBox(farming?"Show farming map pins":"Show STASH markers",maps.visible(group));
        search.setName(farming?"farmingLocationSearch":"stashLocationSearch");search.setToolTipText("Filter cards by type or location name");search.putClientProperty("JTextField.placeholderText","Patch or location");
        JPanel controls=new JPanel(new BorderLayout(0,5));
        JPanel fields=new JPanel(new GridLayout(0,1,0,3));
        JPanel searchRow=new JPanel(new BorderLayout(6,0));JLabel label=new JLabel("Search");label.setForeground(OneManCards.ACCENT);searchRow.add(label,BorderLayout.WEST);searchRow.add(search,BorderLayout.CENTER);
        fields.add(filter);fields.add(searchRow);fields.add(show);fields.add(count);
        controls.add(OneManCards.banner(farming?"Farming patches":"STASH locations", "Choose a location to focus the world map."),BorderLayout.NORTH);
        controls.add(fields,BorderLayout.CENTER);add(controls,BorderLayout.NORTH);add(OneManCards.scroll(cards),BorderLayout.CENTER);
        filter.addActionListener(event->{reload();maps.configure(group,(String)filter.getSelectedItem(),show.isSelected());});
        show.addActionListener(event->maps.configure(group,(String)filter.getSelectedItem(),show.isSelected()));
        search.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent event) {reload();}
            public void removeUpdate(DocumentEvent event) {reload();}
            public void changedUpdate(DocumentEvent event) {reload();}
        });
        reload();OneManTheme.apply(this);
    }
    void setRequirements(Map<String,List<StashRequirements.Row>> requirements)
    {
        this.requirements=requirements;
        selectors.forEach((category,selector)->describe(category,(OneManMapCatalog.Site)selector.getSelectedItem()));
    }
    void chooseCategory(String category)
    {
        show.setSelected(true);search.setText("");filter.setSelectedItem(category);
    }
    void setStatuses(Map<String,String> statuses)
    {
        this.statuses=Collections.unmodifiableMap(new HashMap<>(statuses));
        selectors.forEach((category,selector)->describe(category,(OneManMapCatalog.Site)selector.getSelectedItem()));
    }
    private void reload()
    {
        Map<String,List<OneManMapCatalog.Site>> grouped=new LinkedHashMap<>();
        String query=search.getText().trim().toLowerCase(Locale.ROOT);
        for(String category:maps.categories(group)) if(!category.equals("All")) grouped.put(category,new ArrayList<>());
        int locations=0;
        for(OneManMapCatalog.Site site:maps.sites(group,(String)filter.getSelectedItem())) {
            if(!query.isEmpty() && !(site.category+" "+site.name).toLowerCase(Locale.ROOT).contains(query)) continue;
            grouped.get(site.category).add(site);locations++;
        }
        cards.removeAll();selectors.clear();descriptions.clear();requirementPanels.clear();int types=0;
        for(Map.Entry<String,List<OneManMapCatalog.Site>> row:grouped.entrySet()) if(!row.getValue().isEmpty()) {addCard(row.getKey(),row.getValue());types++;}
        if(types==0) cards.card(OneManCards.text("No matching locations. Try another type or place name."));
        count.setText(locations+" locations • "+types+" "+(types==1?"type":"types"));count.setForeground(OneManCards.MUTED);cards.finish();
    }
    private void addCard(String category,List<OneManMapCatalog.Site> sites)
    {
        JPanel card=OneManCards.card();card.setName((group==OneManMapCatalog.Group.FARMING?"farmingCard:":"stashCard:")+category);
        JPanel header=new JPanel(new BorderLayout(6,0));header.setOpaque(false);
        JLabel icon=new JLabel();icon.setPreferredSize(new Dimension(32,34));maps.icon(icon,category);header.add(icon,BorderLayout.WEST);
        JPanel title=new JPanel(new GridLayout(0,1));title.setOpaque(false);
        JLabel name=new JLabel(category);name.setFont(name.getFont().deriveFont(Font.BOLD));name.setToolTipText(category);title.add(name);
        JLabel size=new JLabel(sites.size()+" "+(sites.size()==1?"location":"locations"));size.setForeground(OneManCards.MUTED);size.setFont(new Font(Font.SANS_SERIF,Font.PLAIN,11));title.add(size);header.add(title,BorderLayout.CENTER);
        JButton map=new JButton("Map");map.setMargin(new Insets(2,5,2,5));map.setToolTipText("Centre the world map on the selected location");header.add(map,BorderLayout.EAST);card.add(header,BorderLayout.NORTH);
        JComboBox<OneManMapCatalog.Site> selector=new JComboBox<>(sites.toArray(new OneManMapCatalog.Site[0]));
        selector.setName((group==OneManMapCatalog.Group.FARMING?"farmingLocation:":"stashLocation:")+category);
        selector.setPreferredSize(new Dimension(1,28));selector.setMinimumSize(new Dimension(0,28));
        for(OneManMapCatalog.Site site:sites) if(site.id.equals(selected.get(category))) selector.setSelectedItem(site);
        JTextArea status=OneManCards.text("");
        selectors.put(category,selector);descriptions.put(category,status);
        JPanel body=new JPanel(new BorderLayout(0,5));body.setOpaque(false);body.add(selector,BorderLayout.NORTH);body.add(status,BorderLayout.CENTER);card.add(body,BorderLayout.CENTER);
        if(group==OneManMapCatalog.Group.STASH) {
            OneManCards required=new OneManCards();
            required.setName("stashRequirements:"+category);requirementPanels.put(category,required);body.add(required,BorderLayout.SOUTH);
        }
        Runnable focus=()-> {
            OneManMapCatalog.Site site=(OneManMapCatalog.Site)selector.getSelectedItem();if(site==null) return;
            selected.put(category,site.id);describe(category,site);maps.focus(group,site);
        };
        selector.addActionListener(event->focus.run());map.addActionListener(event->focus.run());
        describe(category,(OneManMapCatalog.Site)selector.getSelectedItem());cards.card(card);
    }
    private void describe(String category,OneManMapCatalog.Site site)
    {
        if(site==null) return;
        selectors.get(category).setToolTipText(site.name);
        String status=statuses.get(site.id);
        String hint=site.points.get(0).getY()>6400?"Underground map area":site.points.get(0).getPlane()>0?"Floor "+site.points.get(0).getPlane():"Surface location";
        OneManCards required=requirementPanels.get(category);
        if(required!=null) {
            required.removeAll();
            JLabel title=new JLabel("Required items");title.setForeground(OneManCards.ACCENT);required.card(title);
            List<StashRequirements.Row> rows=requirements.get(site.id);
            if(rows==null) required.card(OneManCards.text("Log in to check items. Items stored inside a STASH are not checked."));
            else {
                for(StashRequirements.Row row:rows) {
                    JTextArea item=OneManCards.text("• "+row.name+"\n"+row.state.label);
                    item.setForeground(row.state.color);required.card(item);
                }
                required.card(OneManCards.text("Bank = last observed contents. Open your bank to refresh. Items inside the STASH are not checked."));
            }
            required.finish();
        }
        descriptions.get(category).setText(status==null?(group==OneManMapCatalog.Group.STASH?site.name+"\n":"")+hint:status);
    }
}

package lt.oneman.sync;

import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.MenuAction;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayMenuEntry;

/** Route a user click through RuneLite's public overlay configuration action.
 * ConfigPlugin owns the actual configuration panel; no duplicate settings form.
 */
final class OneManSettings
{
    private OneManSettings() {}

    static OverlayMenuClicked request(Plugin plugin)
    {
        // This is only the action's owning-plugin context, never registered or rendered.
        Overlay context = new Overlay(plugin) {
            @Override public Dimension render(Graphics2D graphics) { return null; }
        };
        return new OverlayMenuClicked(
            new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", plugin.getName()), context);
    }
}

