package lt.oneman.sync;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/** Highlights currently observed NPCs only; no prediction or blast radius. */
final class ShamanMinionOverlay extends Overlay
{
    @Inject private Client client;
    @Inject private OneManSyncConfig config;
    @Inject private ModelOutlineRenderer outlines;
    private volatile MonstersHub hub;

    ShamanMinionOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    void setHub(MonstersHub hub) { this.hub = hub; }

    static Color opacity(Color color, int percent)
    {
        int alpha = color.getAlpha() * Math.max(0, Math.min(100, percent)) / 100;
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
    }

    // One global cosmetic phase: never restarted by spawning, scene changes or configuration.
    static int pulsePercent(long monotonicNanos)
    {
        long period = 2_400_000_000L;
        double phase = Math.floorMod(monotonicNanos, period) / (double) period;
        return (int) Math.round(80 + 20 * Math.cos(2 * Math.PI * phase));
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        MonstersHub currentHub = hub;
        if (currentHub == null || client.getGameState() != GameState.LOGGED_IN || !currentHub.enabled()) return null;
        Color tileColor = opacity(config.monstersShamanColor(), config.monstersShamanTileOpacity());
        Color modelColor = opacity(config.monstersShamanModelColor(), config.monstersShamanModelOpacity());
        Color outlineColor = config.monstersShamanPulse()
            ? opacity(modelColor, pulsePercent(System.nanoTime())) : modelColor;
        Color fillColor = opacity(config.monstersShamanModelColor(), config.monstersShamanFillOpacity());
        for (MonstersHub.Marker marker : currentHub.markers())
        {
            NPC npc = marker.npc;
            if (marker.plane != client.getTopLevelWorldView().getPlane()
                || npc.getWorldView() != client.getTopLevelWorldView() || !MonstersHub.isMinion(npc.getId())) continue;
            if (config.monstersShamanTiles() && tileColor.getAlpha() > 0)
            {
                Polygon tile = Perspective.getCanvasTilePoly(client, marker.location);
                if (tile != null)
                {
                    graphics.setColor(new Color(tileColor.getRed(), tileColor.getGreen(), tileColor.getBlue(), tileColor.getAlpha() * 16 / 100));
                    graphics.fillPolygon(tile);
                    graphics.setColor(tileColor); graphics.drawPolygon(tile);
                }
            }
            if (config.monstersShamanFill() && fillColor.getAlpha() > 0)
            {
                Shape hull = npc.getConvexHull();
                if (hull != null) { graphics.setColor(fillColor); graphics.fill(hull); }
            }
            if (config.monstersShamanOutline() && modelColor.getAlpha() > 0)
                outlines.drawOutline(npc, Math.max(1, Math.min(6, config.monstersShamanOutlineWidth())), outlineColor, 2);
            if (config.monstersShamanLabel() && modelColor.getAlpha() > 0)
            {
                Point text = npc.getCanvasTextLocation(graphics, "Spawn", npc.getLogicalHeight() + 20);
                if (text != null) OverlayUtil.renderTextLocation(graphics, text, "Spawn", modelColor);
            }
        }
        return null;
    }
}

package lt.oneman.sync;

import com.google.gson.Gson;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
final class SlayerLabAccount
{
    static final class Bank
    {
        long seen;
        Map<String,Integer> items = new TreeMap<>();
    }
    @Inject private Gson gson;
    @Inject private ConfigManager configs;
    String profile = "";
    Bank bank = new Bank();
    SlayerLabJournal journal = new SlayerLabJournal();
    private long lastSave;
    boolean bind(String key, long now)
    {
        if (key == null || key.isEmpty()) return false;
        if (profile.equals(key)) return true;
        pause("Profile changed", now);
        profile = key;
        bank = read("bankSnapshot", Bank.class, new Bank());
        journal = read("journal", SlayerLabJournal.class, new SlayerLabJournal());
        if (bank.items == null) bank = new Bank();
        if (journal.active != null) journal.end("Interrupted session recovered", Math.max(journal.active.started, journal.active.updated));
        save(now, true);
        return true;
    }
    private <T> T read(String name, Class<T> type, T fallback)
    {
        try
        {
            String json = configs.getConfiguration(SlayerLabConfig.GROUP, profile, name);
            T data = json == null ? null : gson.fromJson(json, type);
            return data == null ? fallback : data;
        }
        catch (RuntimeException badStoredData) { return fallback; }
    }
    void captureBank(Map<String,Integer> items, long now)
    {
        if (profile.isEmpty()) return;
        bank.items = new TreeMap<>(items); bank.seen = now;
        configs.setConfiguration(SlayerLabConfig.GROUP, profile, "bankSnapshot", gson.toJson(bank));
    }
    void pause(String reason, long now)
    {
        if (profile.isEmpty()) return;
        journal.end(reason, now); save(now, true);
    }
    void save(long now, boolean force)
    {
        if (profile.isEmpty() || (!force && now - lastSave < 30000)) return;
        configs.setConfiguration(SlayerLabConfig.GROUP, profile, "journal", gson.toJson(journal)); lastSave = now;
    }
    String bankAge(long now)
    {
        if (bank.seen <= 0) return "Bank unknown — open your bank to capture a snapshot.";
        return "Bank last opened: " + java.time.Instant.ofEpochMilli(bank.seen) + " (" + Math.max(0, now-bank.seen)/60000
            + " min ago). Snapshot ownership is not current inventory; items may have changed.";
    }
    String preparation(SlayerLabCatalog.Guide guide, Set<String> inventory, Set<String> equipment, long now)
    {
        StringBuilder text = new StringBuilder();
        if (guide != null)
            for (SlayerLabCatalog.Requirement requirement : guide.requirements)
            {
                String status = requirement.status(inventory, equipment);
                if (status.startsWith("MISSING"))
                    status = bank.seen <= 0 ? "NOT CARRIED — bank unknown"
                        : bank.items.entrySet().stream().anyMatch(e -> e.getValue() > 0 && requirement.matches(e.getKey()))
                            ? "TAKE FROM BANK — found in dated snapshot" : "NOT CARRIED / not in dated bank snapshot";
                text.append(requirement.label).append("\n").append(status).append("\n\n");
            }
        text.append("Checklist covers the regular task monster. A manually chosen boss/variant can require different gear. Diary exemptions and protection effects are not verified automatically.\n\n");
        text.append("General supplies: choose your food, combat supplies and an escape/bank teleport. Special protection, charges, quantity and variant suitability still matter.");
        return text.toString();
    }
}

package lt.oneman.sync;

import java.util.*;

/** Manually selected reference advice; never driven by boss combat events. */
final class SlayerLabAdvice
{
    static final String REGULAR = "Regular task monsters";
    static final class Goal
    {
        final String item, reason;
        Goal(String item, String reason) { this.item=item; this.reason=reason; }
        @Override public String toString() { return item; }
    }
    static List<String> variants(String task)
    {
        LinkedHashSet<String> result = new LinkedHashSet<>(); result.add(REGULAR);
        SlayerLabKnowledge.Entry entry = SlayerLabKnowledge.find(task);
        if (entry != null) { result.addAll(entry.variants); result.addAll(entry.targets); }
        return new ArrayList<>(result);
    }
    static String tactics(String task, String variant)
    {
        String name = REGULAR.equals(variant) ? task : variant;
        String n = SlayerLabKnowledge.normalize(name);
        String advice;
        if (n.contains("alchemical hydra")) advice="95 Slayer and an active Hydra task. Choose a dedicated boss setup, floor-protection boots unless diary-exempt, and poison protection. The room's vents and phase changes are central to the encounter: study the strategy guide before entering. Regular-hydra gear notes are not a boss setup.";
        else if (n.contains("araxxor")) advice="92 Slayer and an eligible araxyte/spider task. Venom protection and crush equipment are useful preparation choices. Learn the egg/spider and phase mechanics in the strategy guide. Ordinary araxyte equipment notes are not a complete boss setup.";
        else if (n.contains("cerberus")) advice="91 Slayer and an eligible hellhound task. Bring a dedicated boss setup and ample supplies; spectral spirit shield is a specialised option, not an entry requirement. Learn the ghost and lava mechanics in the strategy guide.";
        else if (n.contains("sire")) advice="85 Slayer and an abyssal demon assignment. This is a multi-phase encounter; prepare suitable equipment for respiratory systems and the main fight. Learn access, transition and area-hazard mechanics first.";
        else if (n.contains("grotesque") || n.equals("dusk") || n.equals("dawn")) advice="75 Slayer, a gargoyle task and an unlocked rooftop bell. Prepare both ranged and melee equipment, and a gargoyle finishing tool. Learn the two-target phases before entering; a regular gargoyle setup is incomplete.";
        else if (n.contains("kraken")) advice="87 Slayer and a matching task. Prepare magic equipment, visible rune supplies or charged weapon supplies. Regular cave kraken and the Kraken boss have different activation procedures; use the guide for the selected version.";
        else if (n.contains("thermonuclear")) advice="93 Slayer and a smoke devil task; wear face protection. Use a dedicated boss setup and study the strategy guide. This single-target boss differs from ordinary smoke devils.";
        else if (n.contains("demonic gorilla")) advice="Monkey Madness II access. Bring equipment for two combat styles and venom/poison precautions appropriate to your route. Read the switching and movement mechanics before starting; these are harder than ordinary black demons.";
        else if (n.contains("basilisk knight")) advice="60 Slayer and The Fremennik Exiles. A mirror shield or V's shield is essential. Knights have much higher health and a different encounter than ordinary basilisks; choose them deliberately for basilisk-jaw hunting.";
        else if (n.contains("lizardman shaman")) advice="Prepare Shayzien armour protection. A Slayer helmet only gains the relevant armour effect after the hard Kourend & Kebos Diary AND speaking to Captain Cleive. Ranged equipment aids movement; study jumps, acid and summons before fighting.";
        else if (n.contains("wyvern")) advice="Use a suitable wyvern shield; ordinary anti-dragon shields and antifire alone are not equivalent. Choose the precise wyvern variant and check its Slayer/access requirements. Ancient wyverns require more preparation than lower Fossil Island variants.";
        else if (n.contains("hydra") || n.contains("wyrm") || n.contains("drake")) advice="Karuulm floor protection is required unless elite Kourend & Kebos Diary exempt. Select the correct chamber and monster variant; verify dragonfire/poison precautions in the individual guide. Alchemical Hydra is a distinct boss encounter.";
        else advice="Check the chosen monster's level, access, attack types and equipment before travelling. Variants can have different protection, combat difficulty and drops. The source list includes superior monsters: these are incidental spawns, not always a selectable hunting destination.";
        return name+"\n\n"+advice+"\n\nStatic reference only: this panel does not analyse attacks, suggest prayers or guide movement during combat.\n\nStrategy guide:\n"+strategy(name);
    }
    static String strategy(String name)
    {
        if (name.equals("Dawn") || name.equals("Dusk") || name.equals("Guardian of Dawn") || name.equals("Guardian of Dusk")) name="Grotesque Guardians";
        return "https://oldschool.runescape.wiki/w/" + java.net.URLEncoder.encode(name.replace(' ','_')+"/Strategies", java.nio.charset.StandardCharsets.UTF_8);
    }
    static List<Goal> goals(String task)
    {
        String n=SlayerLabKnowledge.normalize(task); List<Goal> result=new ArrayList<>();
        if(n.contains("abyssal")) result.add(new Goal("Abyssal whip","Melee weapon upgrade; regular abyssal demons."));
        if(n.contains("horror")) result.add(new Goal("Black mask","Component of a Slayer helmet; cave horrors."));
        if(n.contains("kraken")) { result.add(new Goal("Trident of the seas","Powered magic weapon; check charged and uncharged forms.")); result.add(new Goal("Kraken tentacle","Component for an abyssal tentacle.")); }
        if(n.contains("hydra")) { result.add(new Goal("Hydra leather","Alchemical Hydra drop used for ferocious gloves.")); result.add(new Goal("Hydra's claw","Alchemical Hydra drop used for a dragon hunter lance.")); }
        if(n.contains("smoke")) result.add(new Goal("Occult necklace","Magic necklace upgrade."));
        if(n.contains("basilisk")) result.add(new Goal("Basilisk jaw","Basilisk Knights drop used for a Neitiznot faceguard."));
        if(n.contains("black demon") || n.contains("monkey")) result.add(new Goal("Zenyte shard","Demonic gorilla drop for zenyte jewellery."));
        if(n.contains("lizardman")) result.add(new Goal("Dragon warhammer","Special-attack weapon upgrade; shamans."));
        if(n.contains("gargoyle")) result.add(new Goal("Granite maul","Special-attack weapon; ordinary gargoyles."));
        if(n.contains("kurask")) result.add(new Goal("Leaf-bladed battleaxe","Weapon option against kurask/turoth."));
        if(n.contains("spiritual")) result.add(new Goal("Dragon boots","Spiritual mage drop; melee boots upgrade."));
        if(n.contains("hellhound") || n.contains("cerberus")) result.add(new Goal("Primordial crystal","Cerberus drop used to upgrade dragon boots."));
        if(n.contains("araxy") || n.contains("araxxor")) result.add(new Goal("Araxyte fang","Araxxor drop used for an amulet of rancour."));
        return result;
    }
    static String loot(String task,String goal,SlayerLabAccount.Bank bank,SlayerLabJournal.Session session)
    {
        StringBuilder out=new StringBuilder("Ironman targets — choose a goal below. These are upgrade ideas, not a guaranteed drop or a personalised progression plan. Boss-only goals require the corresponding variant.\n\n");
        for(Goal g:goals(task)) out.append(g.item).append(" — ").append(g.reason).append("\n");
        out.append("\nSelected goal: ").append(goal.isEmpty()?"none":goal);
        if(!goal.isEmpty()) {
            String key=SlayerLabKnowledge.normalize(goal);
            out.append("\nBank snapshot count: ").append(bank.seen==0?"unknown":Integer.toString(bank.items.getOrDefault(key,0)));
            out.append("\nObserved this session: ").append(session==null?0:session.loot.getOrDefault(key,0));
        }
        out.append("\n\nDated bank counts may be stale; equipped items and alternate item forms are not included in the bank count.\nAttributed session loot:\n").append(session==null?"No session":session.loot);
        return out.toString();
    }
    static String comparison(SlayerLabLocations.Destination d,String task) {
        String description=comparison(d);
        if(SlayerLabCatalog.taskKey(task).equals("bloodvelds")&&(d.name.equals("Iorwerth Dungeon")||d.name.equals("Meiyerditch Laboratories")))
            return description.replace("Cannon: not verified for this chamber — check location guide","Cannon: ALLOWED in the Bloodveld chamber; verify the setup spot in Location guide");
        return description;
    }
    static String comparison(SlayerLabLocations.Destination d)
    {
        String n=d.name.toLowerCase(Locale.ROOT);
        String cannon=n.contains("catacombs")||n.contains("tower")||n.contains("kraken")||n.contains("god wars")?"Cannon: NOT ALLOWED":n.contains("stronghold slayer")?"Cannon: ALLOWED (matching active task required)":"Cannon: not verified for this chamber — check location guide";
        String bank=n.contains("taverley")?"Falador/Taverley banking route":n.contains("tower")?"Canifis bank":n.contains("karuulm")?"Mount Karuulm bank":n.contains("devil")?"Castle Wars bank":n.contains("iorwerth")?"Prifddinas banks":n.contains("swamp")?"Lumbridge bank":n.contains("edgeville")?"Edgeville bank":n.contains("sewers")?"Varrock banks":"Choose a bank teleport; no nearest-bank path is calculated";
        String multi=n.contains("catacombs")?"Multi-combat":"Combat zones vary by room/variant; check before area attacks";
        return d+"\n"+d.access+"\n"+cannon+"\n"+multi+"\nBank: "+bank+"\nPvP: "+(d.wilderness?"Wilderness — items at risk":d.entrance == null ? "Check assigned area guide before travel" : "This entrance is outside Wilderness")+"\n";
    }
}

package lt.oneman.sync;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Curated preparation notes. Unknown tasks deliberately fall back to the Wiki. */
final class SlayerLabCatalog
{
    static final class Requirement
    {
        final String label;
        final boolean equip;
        final List<String> alternatives;
        Requirement(String label, boolean equip, String... alternatives)
        {
            this.label = label;
            this.equip = equip;
            this.alternatives = Arrays.asList(alternatives);
        }
        boolean matches(String item)
        {
            String name = normalize(item);
            for (String alternative : alternatives)
            {
                if (alternative.equals("*slayer helmet") && name.contains("slayer helmet")) return true;
                if (alternative.equals("*leaf-bladed") && name.startsWith("leaf-bladed ")) return true;
                if (name.equals(alternative)) return true;
            }
            return false;
        }
        String status(Set<String> inventory, Set<String> equipment)
        {
            if (equipment.stream().anyMatch(this::matches)) return "READY — equipped";
            if (inventory.stream().anyMatch(this::matches))
            {
                boolean onlyWeapon = inventory.stream().filter(this::matches).allMatch(n -> normalize(n).equals("brine sabre"));
                return equip || onlyWeapon ? "EQUIP — in inventory" : "READY — in inventory";
            }
            return "MISSING — not carried";
        }
    }
    static final class Guide
    {
        final String task, locations, advice;
        final List<Requirement> requirements;
        Guide(String task, String locations, String advice, Requirement... requirements)
        {
            this.task = task;
            this.locations = locations;
            this.advice = advice;
            this.requirements = Arrays.asList(requirements);
        }
        String wikiUrl() { return wiki(task); }
    }
    private static final Map<String, Guide> GUIDES = new LinkedHashMap<>();
    private static final Set<String> CURATED = new HashSet<>();
    private static Requirement worn(String label, String... names) { return new Requirement(label, true, names); }
    private static Requirement carried(String label, String... names) { return new Requirement(label, false, names); }
    private static void add(String task, String locations, String advice, Requirement... requirements)
    { CURATED.add(normalize(task)); GUIDES.put(normalize(task), new Guide(task, locations, advice, requirements)); }
    static
    {
        add("Blue dragons", "Taverley Dungeon: blue dragon chamber. Enter south of Taverley; dusty key on the long route OR 70 Agility pipe shortcut. Heroes' Guild basement: Heroes' Quest required.",
            "Adults: prepare dragonfire protection appropriate to your setup (for example anti-dragon shield plus antifire). Baby blue dragons also count and do not breathe dragonfire. Food, ammo/runes and a bank teleport are recommended; quantities depend on your setup.");
        add("Gargoyles", "Slayer Tower: upper floor; basement is task-only. Reach the tower north-west of Canifis (Morytania access).", "75 Slayer. Carry a finishing tool; Gargoyle Smasher does not remove the tool requirement.", carried("Rock hammer / granite hammer / rock thrownhammer", "rock hammer", "granite hammer", "rock thrownhammer"));
        add("Banshees", "Slayer Tower: ground floor, north-west of Canifis. Twisted banshees: Catacombs of Kourend.", "15 Slayer. Wear sound protection before fighting.", worn("Earmuffs or Slayer helmet", "earmuffs", "*slayer helmet"));
        add("Aberrant spectres", "Slayer Tower: middle floor. Stronghold Slayer Cave: beneath the Gnome Stronghold. Deviant spectres: Catacombs of Kourend.", "60 Slayer. Wear nose protection; herb storage and food are useful.", worn("Nose peg or Slayer helmet", "nose peg", "*slayer helmet"));
        add("Dust devils", "Catacombs of Kourend: enter beneath the Kourend Castle statue. Smoke Dungeon: desert well west of Pollnivneach; requires starting Desert Treasure I.", "65 Slayer. Wear face protection. Food, ammo/runes and teleport are setup-dependent.", worn("Facemask or Slayer helmet", "facemask", "*slayer helmet"));
        add("Basilisks", "Fremennik Slayer Dungeon: east of Rellekka. Basilisk Knights: Jormungand's Prison after The Fremennik Exiles.", "40 Slayer for regular basilisks; knights require 60 Slayer and quest access. Slayer helmet does not replace the shield.", worn("Mirror shield or V's shield", "mirror shield", "v's shield"));
        add("Cockatrice", "Fremennik Slayer Dungeon: east of Rellekka, cockatrice chamber.", "25 Slayer. Equip a protective shield; Slayer helmet does not replace it.", worn("Mirror shield or V's shield", "mirror shield", "v's shield"));
        add("Rockslugs", "Fremennik Slayer Dungeon: east of Rellekka, second chamber. Lumbridge Swamp Caves: cave lighting and gas precautions required.", "20 Slayer. Salt is consumed on each finishing kill unless using a brine sabre. Check quantity for your task.", carried("Bag of salt or brine sabre", "bag of salt", "brine sabre"));
        add("Lizards", "Kharidian Desert: desert lizards near the area south-east of Shantay Pass. Check the task Wiki for exact spawns.", "22 Slayer for desert lizards. Ice coolers finish desert lizards; quantity depends on kills. Desert heat supplies recommended.", carried("Ice cooler", "ice cooler"));
