package lt.oneman.sync;

import java.awt.*;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.*;

/** Pulsing entrance indicator, drawn only when the point is visible on the minimap. */
final class SlayerLabMinimapOverlay extends Overlay
{
    private final Client client;
    private final OneManSlayerHelper plugin;
    @Inject SlayerLabMinimapOverlay(Client client, OneManSlayerHelper plugin)
    {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }
    @Override public Dimension render(Graphics2D graphics)
    {
        WorldPoint target = plugin.navigationTarget();
        if (target == null || client.getLocalPlayer() == null || target.getPlane() != client.getTopLevelWorldView().getPlane()
            || client.getTopLevelWorldView().isInstance()) return null;
        LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), target);
        boolean directionOnly = false;
        WorldPoint player = client.getLocalPlayer().getWorldLocation();
        if ((player.getY() >= 6400) != (target.getY() >= 6400)) return null;
        if (local == null || player.distanceTo(target) > 15)
        {
            double dx = target.getX() - player.getX(), dy = target.getY() - player.getY();
            double length = Math.hypot(dx, dy);
            if (length == 0) return null;
            WorldPoint probe = new WorldPoint(player.getX() + (int) Math.round(15 * dx / length),
                player.getY() + (int) Math.round(15 * dy / length), player.getPlane());
            local = LocalPoint.fromWorld(client.getTopLevelWorldView(), probe);
            directionOnly = true;
        }
        if (local == null) return null;
        net.runelite.api.Point point = Perspective.localToMinimap(client, local);
        if (point == null) return null;
        boolean bright = (client.getTickCount() / 2) % 2 == 0;
        graphics.setColor(bright ? new Color(100, 220, 255) : new Color(30, 140, 240));
        graphics.setStroke(new BasicStroke(2));
        if (directionOnly)
        {
            net.runelite.api.Point centre = Perspective.localToMinimap(client, client.getLocalPlayer().getLocalLocation());
            if (centre == null) return null;
            double angle = Math.atan2(point.getY() - centre.getY(), point.getX() - centre.getX());
            double vx = Math.cos(angle), vy = Math.sin(angle);
            int x = point.getX(), y = point.getY();
            graphics.fillPolygon(new int[]{x + (int)(7*vx), x + (int)(-5*vx-5*vy), x + (int)(-5*vx+5*vy)},
                new int[]{y + (int)(7*vy), y + (int)(-5*vy+5*vx), y + (int)(-5*vy-5*vx)}, 3);
            return null;
        }
        graphics.drawOval(point.getX() - 7, point.getY() - 7, 14, 14);
        graphics.fillPolygon(new int[]{point.getX()-5,point.getX()+5,point.getX()},
            new int[]{point.getY()-11,point.getY()-11,point.getY()-3},3);
        return null;
    }
}

package lt.oneman.sync;

import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/** Own resource state only; no NPC, attack or projectile input. */
final class SlayerLabPrayer
{
    private enum ActivePrayer
    {
        THICK_SKIN(VarbitID.PRAYER_THICKSKIN),
        BURST_OF_STRENGTH(VarbitID.PRAYER_BURSTOFSTRENGTH),
        CLARITY_OF_THOUGHT(VarbitID.PRAYER_CLARITYOFTHOUGHT),
        SHARP_EYE(VarbitID.PRAYER_SHARPEYE),
        MYSTIC_WILL(VarbitID.PRAYER_MYSTICWILL),
        ROCK_SKIN(VarbitID.PRAYER_ROCKSKIN),
        SUPERHUMAN_STRENGTH(VarbitID.PRAYER_SUPERHUMANSTRENGTH),
        IMPROVED_REFLEXES(VarbitID.PRAYER_IMPROVEDREFLEXES),
        RAPID_RESTORE(VarbitID.PRAYER_RAPIDRESTORE),
        RAPID_HEAL(VarbitID.PRAYER_RAPIDHEAL),
        PROTECT_ITEM(VarbitID.PRAYER_PROTECTITEM),
        HAWK_EYE(VarbitID.PRAYER_HAWKEYE),
        MYSTIC_LORE(VarbitID.PRAYER_MYSTICLORE),
        STEEL_SKIN(VarbitID.PRAYER_STEELSKIN),
        ULTIMATE_STRENGTH(VarbitID.PRAYER_ULTIMATESTRENGTH),
        INCREDIBLE_REFLEXES(VarbitID.PRAYER_INCREDIBLEREFLEXES),
        PROTECT_FROM_MAGIC(VarbitID.PRAYER_PROTECTFROMMAGIC),
        PROTECT_FROM_MISSILES(VarbitID.PRAYER_PROTECTFROMMISSILES),
        PROTECT_FROM_MELEE(VarbitID.PRAYER_PROTECTFROMMELEE),
        EAGLE_EYE(VarbitID.PRAYER_EAGLEEYE),
        MYSTIC_MIGHT(VarbitID.PRAYER_MYSTICMIGHT),
        RETRIBUTION(VarbitID.PRAYER_RETRIBUTION),
        REDEMPTION(VarbitID.PRAYER_REDEMPTION),
        SMITE(VarbitID.PRAYER_SMITE),
        CHIVALRY(VarbitID.PRAYER_CHIVALRY),
        DEADEYE(VarbitID.PRAYER_DEADEYE),
        MYSTIC_VIGOUR(VarbitID.PRAYER_MYSTICVIGOUR),
        PIETY(VarbitID.PRAYER_PIETY),
        PRESERVE(VarbitID.PRAYER_PRESERVE),
        RIGOUR(VarbitID.PRAYER_RIGOUR),
        AUGURY(VarbitID.PRAYER_AUGURY);
        final int varbit;
        ActivePrayer(int varbit) { this.varbit=varbit; }
    }
    static List<String> active(Client client)
    {
        List<String> result=new ArrayList<>();
        for(ActivePrayer prayer:ActivePrayer.values())
            if(client.getVarbitValue(prayer.varbit)!=0) result.add(prayer.name().replace('_',' '));
        return result;
    }
    static final int WINDOW_TICKS = 50, MIN_TICKS = 20;
    private static final Pattern POTION = Pattern.compile("^(prayer potion|prayer mix|super restore|super restore mix)\\s*\\(([1-4])\\)$");
    static final class Doses
    {
        int prayer, restore;
        int total() { return prayer + restore; }
    }
    static Doses doses(Map<String,Integer> items)
    {
        Doses result = new Doses();
        for(Map.Entry<String,Integer> item:items.entrySet())
        {
            if(item.getValue()<=0) continue;
            Matcher match=POTION.matcher(SlayerLabKnowledge.normalize(item.getKey()));
            if(!match.matches()) continue;
            int count=Integer.parseInt(match.group(2))*item.getValue();
            if(match.group(1).startsWith("prayer")) result.prayer+=count;
            else result.restore+=count;
        }
        return result;
    }
    private final Deque<Integer> losses = new ArrayDeque<>();
    private int previous=-1, lost;
    private String signature="";
    private boolean pointsLow, dosesLow;
    void reset()
    {
        resetEstimate(); pointsLow=false; dosesLow=false;
    }
    void resetEstimate()
    {
        losses.clear(); lost=0; previous=-1; signature="";
    }
    void observe(int points, String activeSignature)
    {
        if(points<0) { resetEstimate(); return; }
        if(!Objects.equals(signature,activeSignature) || (previous>=0 && points>previous)) resetEstimate();
        signature=activeSignature;
        if(activeSignature.isEmpty()) { losses.clear(); lost=0; previous=points; return; }
        if(previous>=0)
        {
            int loss=Math.max(0,previous-points); losses.addLast(loss); lost+=loss;
            if(losses.size()>WINDOW_TICKS) lost-=losses.removeFirst();
        }
        previous=points;
    }
    double remainingSeconds(int points)
    {
        if(points<=0) return 0;
        if(signature.isEmpty() || losses.size()<MIN_TICKS || lost<2) return Double.NaN;
        return points*losses.size()*0.6/lost;
    }
    List<String> warnings(int points, Doses doses, SlayerLabConfig config)
    {
        List<String> out=new ArrayList<>();
        if(config.prayerPointsWarning()>0 && points<config.prayerPointsWarning()) out.add("PRAYER POINTS LOW — below "+config.prayerPointsWarning());
        if(config.prayerDosesWarning()>0 && doses.total()<config.prayerDosesWarning()) out.add("PRAYER / RESTORE DOSES LOW — below "+config.prayerDosesWarning());
        return out;
    }
    List<String> crossed(int points, Doses doses, SlayerLabConfig config)
    {
        boolean newPoints=config.prayerPointsWarning()>0 && points<config.prayerPointsWarning();
        boolean newDoses=config.prayerDosesWarning()>0 && doses.total()<config.prayerDosesWarning();
        List<String> result=new ArrayList<>();
        if(newPoints && !pointsLow) result.add("Prayer points below "+config.prayerPointsWarning());
        if(newDoses && !dosesLow) result.add("Prayer / restore doses below "+config.prayerDosesWarning());
        pointsLow=newPoints; dosesLow=newDoses;
        return result;
    }
    String describe(int points,int level,List<String> active,Doses doses,SlayerLabConfig config)
    {
        List<String> warnings=warnings(points,doses,config);
        double seconds=remainingSeconds(points);
        String estimate=points==0?"empty":active.isEmpty()?"no active prayers":Double.isNaN(seconds)?"collecting stable usage (at least 12 seconds and 2 points lost)":String.format(Locale.ROOT,"~%dm %02ds",(int)seconds/60,(int)seconds%60);
        return "PRAYER RESOURCE MONITOR\n\nPoints: "+points+" / "+level
            +"\n\n"+(warnings.isEmpty()?"No chosen warning threshold crossed.":String.join("\n",warnings))
            +"\n\nPrayer potion / mix doses: "+doses.prayer+"\nSuper restore / mix doses: "+doses.restore
            +"\nCombined carried doses: "+doses.total()
            +"\n\nEstimated time until empty: "+estimate
            +"\n\nACTIVE NOW\n"+(active.isEmpty()?"None":String.join("\n",active))
            +"\n\nThis lists prayers you have already enabled. It does not choose prayers or inspect enemy attacks."
            +"\n\nTime uses observed point losses over up to 30 seconds of stable usage (0.6 s/game tick). Changing prayers, equipment or restoring points resets the sample. External drains, flicking, regeneration and lag can make estimates unreliable."
            +"\n\nDoses are carried unnoted Prayer potions, Super restores and their mixes only. Sanfew serum, blighted potions, bank items and other restoration sources are not included. Doses are not equivalent restoration amounts."
            +"\n\nWarning limits and optional desktop alerts: OneMan Sync settings. This monitor works without a Slayer assignment.";
    }
}

package lt.oneman.sync;

import java.util.*;
import java.util.regex.*;

final class SlayerLabSupplies
{
    static final class Counts
    {
        int food, doses, ammo, runes;
        final Map<String, Integer> potions = new TreeMap<>();
        final Map<String, Integer> runeStacks = new TreeMap<>();
        String warnings(SlayerLabConfig config)
        {
            List<String> warnings = new ArrayList<>();
            if (config.foodWarning() > 0 && food < config.foodWarning()) warnings.add("FOOD LOW (your threshold " + config.foodWarning() + ")");
            if (config.doseWarning() > 0 && doses < config.doseWarning()) warnings.add("POTION DOSES LOW (total)");
            if (config.combatStyle() == SlayerLabConfig.CombatStyle.RANGED && config.ammoWarning() > 0 && ammo < config.ammoWarning()) warnings.add("VISIBLE AMMO LOW");
            if (config.combatStyle() == SlayerLabConfig.CombatStyle.MAGIC && config.runeWarning() > 0 && runes < config.runeWarning()) warnings.add("VISIBLE RUNES LOW — check each required rune type");
            return String.join("\n", warnings);
        }
        String describe(SlayerLabConfig config)
        {
            String warning = warnings(config);
            StringBuilder out = new StringBuilder("Supplies\nFood: " + food + "\nPotion doses: " + doses
                + "\nAmmo: " + ammo + "\nRunes: " + runes);
            if (!warning.isEmpty()) out.append("\n\nLow supplies\n").append(warning);
            appendItems(out, "Potions · doses", potions);
            appendItems(out, "Runes · quantity", runeStacks);
            out.append("\n\nInventory & equipped items only; stored runes/ammo and weapon charges excluded.");
            return out.toString();
        }
    }
    private static void appendItems(StringBuilder out, String heading, Map<String,Integer> items)
    {
        if (items.isEmpty()) return;
        out.append("\n\n").append(heading);
        items.forEach((name, count) -> out.append("\n").append(name).append(" · ").append(count));
    }
    private static final Pattern DOSES = Pattern.compile("\\((\\d+)\\)$");
    static Counts count(Map<String, Integer> items, Set<String> edible, Set<String> drinkable)
    {
        Counts counts = new Counts();
        for (Map.Entry<String,Integer> item : items.entrySet())
        {
            String name = SlayerLabKnowledge.normalize(item.getKey()); int quantity = item.getValue();
            if (edible.contains(name)) counts.food += quantity;
            Matcher dose = DOSES.matcher(name);
            if (drinkable.contains(name) && dose.find())
            {
                int n = Integer.parseInt(dose.group(1));
                if (n >= 1 && n <= 6) { counts.doses += n * quantity; counts.potions.put(name, n * quantity); }
            }
            if (name.endsWith(" rune")) { counts.runes += quantity; counts.runeStacks.put(name, quantity); }
            if (name.matches(".*(?:arrow|arrows|bolt|bolts|dart|darts|javelin|javelins|throwing knife|throwing knives)(?: \\(.*\\))?$") && !name.contains("tips")) counts.ammo += quantity;
        }
        return counts;
    }
}

package lt.oneman.sync;

import java.util.*;

/** Short reference routes. Carried items do not imply charges, spell access or diary completion. */
final class SlayerLabTravel
{
    static boolean slayerRing(Set<String> carried)
    { return carried.stream().anyMatch(n -> n.equals("slayer ring (eternal)") || n.matches("slayer ring \\([1-8]\\)")); }

    static String route(SlayerLabLocations.Destination d, Set<String> carried, Set<String> quests)
    {
        String n=d.name.toLowerCase(Locale.ROOT);
        StringBuilder out=new StringBuilder(d.name+"\n");
        // Specific destinations only: Stronghold of Security has no Slayer-ring teleport.
        if(n.equals("slayer tower") || n.equals("fremennik slayer dungeon") || n.equals("stronghold slayer cave"))
            out.append("Slayer ring → ").append(d.name).append(slayerRing(carried)?" [carried]\n":" [charged ring needed]\n");
        if(n.equals("catacombs of kourend"))
            out.append("Xeric's talisman → Xeric's Heart → statue entrance\nNeeds charges + Heart unlocked\n")
                .append("Kourend Castle Teleport → statue entrance\nStandard · 48 Magic · Client of Kourend\n");
        if(n.equals("slayer tower")) out.append("Fairy ring CKS → walk north to tower\nNeeds fairy-ring access\n");
        if(n.equals("fremennik slayer dungeon")) out.append("Fairy ring AJR → nearby cave entrance\nNeeds fairy-ring access\n");
        if(n.contains("karuulm"))
            out.append("Rada's blessing 3/4 → Mount Karuulm\nNeeds hard/elite Kourend & Kebos Diary; 3 has daily limit\nFairy ring CIR → walk north up volcano\nNeeds fairy-ring access\n");
        if(n.equals("chasm of fire")) out.append("Fairy ring DJR → nearby chasm entrance\nNeeds fairy-ring access\n");
        if(n.contains("taverley"))
            out.append("Falador teleport → walk north-west to dungeon\nStandard · 37 Magic, or teleport tablet\n");
        if(n.equals("smoke devil dungeon"))
            out.append("Ring of dueling → Castle Wars → walk south-west\nNeeds charged ring\n");
        if(n.equals("stronghold slayer cave"))
            out.append("Royal seed pod → Grand Tree → cave\n")
                .append(carried.contains("royal seed pod") && quests.contains("Monkey Madness II")?"CARRIED + quest completed\n":"Needs pod + verified Monkey Madness II\n");
        String quest=n.contains("heroes")?"Heroes' Quest":n.contains("iorwerth")?"Song of the Elves":n.contains("harmless")?"Cabin Fever":n.contains("lighthouse")?"Horror from the Deep":n.contains("wyvern cave")?"Bone Voyage":n.equals("slayer tower")||n.contains("spider")?"Priest in Peril":"";
        if(!quest.isEmpty()) out.append(quest).append(quests.contains(quest)?" ✓\n":" required\n");
        // Uncurated destinations keep their entrance note, rather than inventing a fastest route.
        if(out.toString().equals(d.name+"\n") || !quest.isEmpty()) out.append(d.access).append('\n');
        if(d.wilderness) out.append("Wilderness · PvP and item-loss risk\n");
        return out.append('\n').toString();
    }
}

package lt.oneman.sync;

