/** Passive preparation hints, calculated on the client thread. */
final class SlayerRequirementOverlay extends OverlayPanel
{
    static final class Row {
        final String label, status; final Color color;
        Row(String label, String status, Color color) { this.label=label;this.status=status;this.color=color; }
    }
    @Inject private OneManSyncConfig config;
    volatile List<Row> rows=Collections.emptyList();
    SlayerRequirementOverlay() { setPosition(OverlayPosition.TOP_LEFT); }
    static Row row(SlayerLabCatalog.Requirement requirement, Set<String> inventory, Set<String> equipment,
                   Map<String,Integer> bank, boolean bankKnown) {
        if(equipment.stream().anyMatch(requirement::matches))return new Row(requirement.label,"Equipped",Color.GREEN);
        if(inventory.stream().anyMatch(requirement::matches))return new Row(requirement.label,requirement.equip?"Equip":"Carried",Color.GREEN);
        if(bankKnown && bank.entrySet().stream().anyMatch(e->e.getValue()>0&&requirement.matches(e.getKey())))
            return new Row(requirement.label,"In bank",new Color(190,130,255));
        return new Row(requirement.label,bankKnown?"Missing":"Bank unknown",bankKnown?new Color(255,90,90):Color.GRAY);
    }
    @Override public Dimension render(Graphics2D graphics) {
        if(!config.slayerRequirementsOverlay()||rows.isEmpty())return null;
        panelComponent.getChildren().add(TitleComponent.builder().text("Slayer items").build());
        for(Row row:rows) {
            panelComponent.getChildren().add(LineComponent.builder().left(row.label).leftColor(row.color).build());
            panelComponent.getChildren().add(LineComponent.builder().left("  "+row.status).leftColor(row.color).build());
        }
        return super.render(graphics);
    }
}

package lt.oneman.sync;

import java.awt.*;
import java.awt.geom.Ellipse2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Only projects nearby static STASH coordinates; never scans the scene. */
final class StashMinimapOverlay extends Overlay
{
    private static final int[] MINIMAPS={InterfaceID.Toplevel.MINIMAP,InterfaceID.ToplevelOsrsStretch.MINIMAP,InterfaceID.ToplevelPreEoc.MINIMAP};
    @Inject private Client client;
    @Inject private OneManMapLocations maps;
    StashMinimapOverlay() { setPosition(OverlayPosition.DYNAMIC);setLayer(OverlayLayer.ABOVE_WIDGETS); }
    @Override public Dimension render(Graphics2D graphics)
    {
        if(client.getGameState()!=GameState.LOGGED_IN || client.getLocalPlayer()==null) return null;
        Widget minimap=null;
        for(int id:MINIMAPS) { Widget widget=client.getWidget(id);if(widget!=null&&!widget.isHidden()) {minimap=widget;break;} }
        if(minimap==null || minimap.getWidth()<16 || minimap.getHeight()<16) return null;
        Rectangle bounds=minimap.getBounds();if(bounds==null) return null;
        double radius=Math.min(bounds.width,bounds.height)/2.0-6;
        Graphics2D g=(Graphics2D)graphics.create();
        g.clip(new Ellipse2D.Double(bounds.getCenterX()-radius,bounds.getCenterY()-radius,radius*2,radius*2));
        try {
            for(OneManMapCatalog.Site site:maps.minimapStashes()) for(WorldPoint world:site.points) {
                if(world.getPlane()!=client.getPlane()) continue;
                LocalPoint local=LocalPoint.fromWorld(client,world);if(local==null) continue;
                net.runelite.api.Point point=Perspective.localToMinimap(client,local);if(point==null) continue;
                g.setColor(Color.BLACK);g.fillOval(point.getX()-4,point.getY()-4,8,8);
                g.setColor(site.color);g.fillOval(point.getX()-3,point.getY()-3,6,6);
            }
        } finally { g.dispose(); }
        return null;
    }
}

package lt.oneman.sync;

import java.awt.Color;
