import javax.swing.event.DocumentListener;
import net.runelite.api.*;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.LinkBrowser;

/** Read-only game evidence plus explicitly separate account-scoped notes. No web dependency. */
@Singleton
final class UnlocksHub
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configs;
    @Inject private OneManSyncConfig config;
    @Inject private ItemManager items;
    @Inject private Gson gson;
    private final UnlockCatalog catalog=new UnlockCatalog();
    static final class Saved
    {
        Set<String> manual=new HashSet<>(), favourites=new HashSet<>();
        Map<String,Long> observed=new HashMap<>();
    }
    private Saved saved=new Saved();
    private String profile="";
    private boolean active,dirty;
    private int waitTicks,lastTick;
    private volatile List<UnlockCatalog.Result> snapshot=Collections.emptyList();
    private volatile Set<String> favourites=Collections.emptySet();
    private volatile boolean accountReady;
    private String lastSignature="";
    private Panel panel;

    void startUp()
    {
        active=true;dirty=true;waitTicks=8;lastTick=Integer.MIN_VALUE;profile="";
        clear();publish(new UnlockCatalog.Facts());
    }
    void shutDown()
    {
        active=false;clear();snapshot=Collections.emptyList();
        SwingUtilities.invokeLater(()->panel=null);
    }
    private void clear()
    {
        profile="";saved=new Saved();accountReady=false;favourites=Collections.emptySet();
        lastSignature="";
    }
    void onGameStateChanged(GameStateChanged event)
    {
        if(!active)return;
        clear();waitTicks=8;dirty=true;lastTick=Integer.MIN_VALUE;publish(new UnlockCatalog.Facts());
    }
    void changed() {dirty=true;}
    void onConfigChanged()
    {
        if(!active)return;
        SwingUtilities.invokeLater(()->{if(panel!=null)panel.rebuild();});
    }
    private boolean bind()
    {
        String next=configs.getRSProfileKey();
        if(next==null||next.isEmpty())return false;
        if(!profile.equals(next)) {
            clear();publish(new UnlockCatalog.Facts());lastTick=Integer.MIN_VALUE;profile=next;
            try {
                String data=configs.getConfiguration("one-man-sync",profile,"unlocksHubProgress");
                if(data!=null) {
                    Saved loaded=gson.fromJson(data,Saved.class);
                    if(loaded!=null&&loaded.manual!=null&&loaded.favourites!=null&&loaded.observed!=null)saved=loaded;
                }
            } catch(RuntimeException ignored) {saved=new Saved();}
            // Ignore stale/unrecognised IDs and malformed timestamps rather than breaking the Hub.
            saved.manual.removeIf(id->!catalog.byId.containsKey(id)||!catalog.byId.get(id).manualAllowed());
            saved.favourites.retainAll(catalog.byId.keySet());
            saved.observed.entrySet().removeIf(e->!catalog.byId.containsKey(e.getKey())||!"ITEM".equals(catalog.byId.get(e.getKey()).mode)||e.getValue()==null||e.getValue()<=0);
            observe(client.getItemContainer(InventoryID.INV));
            observe(client.getItemContainer(InventoryID.WORN));
            dirty=true;
        }
        accountReady=true;
        return true;
    }
    void onGameTick()
    {
        if(!active||client.getGameState()!=GameState.LOGGED_IN||client.getLocalPlayer()==null)return;
        if(waitTicks>0){waitTicks--;return;}
        if(!bind())return;
        int tick=client.getTickCount();
        long elapsed=(long)tick-lastTick;
        if(elapsed>=0&&elapsed<10)return;
        if(!dirty&&elapsed>=0&&elapsed<100)return;
        dirty=false;lastTick=tick;
        UnlockCatalog.Facts facts=new UnlockCatalog.Facts();facts.live=true;
        for(Quest quest:Quest.values())try {facts.quests.put(quest,quest.getState(client));}catch(RuntimeException ignored) { }
        for(Skill skill:Skill.values())if(skill!=Skill.OVERALL)facts.skills.put(skill,client.getRealSkillLevel(skill));
        Set<Integer> bits=new HashSet<>();
        for(UnlockCatalog.Entry entry:catalog.entries)if(entry.varbit>=0)bits.add(entry.varbit);
        for(int bit:bits)try {facts.bits.put(bit,client.getVarbitValue(bit));}catch(RuntimeException ignored) { }
        publish(facts);
    }
    void onItemContainerChanged(ItemContainerChanged event)
    {
        if(!active||!accountReady||client.getGameState()!=GameState.LOGGED_IN||!profile.equals(configs.getRSProfileKey()))return;
        int id=event.getContainerId();
        if(id==InventoryID.INV||id==InventoryID.WORN||id==InventoryID.BANK)observe(event.getItemContainer());
    }
    private void observe(ItemContainer container)
    {
        if(container==null)return;
        boolean changed=false;
        for(Item item:container.getItems()) {
            if(item==null||item.getId()<0||item.getQuantity()<=0)continue;
            ItemComposition def=items.getItemComposition(item.getId());
            if(def==null)continue;
            if(def.getNote()!=-1)def=items.getItemComposition(def.getLinkedNoteId());
            if(def==null||def.getPlaceholderTemplateId()!=-1||def.getName()==null)continue;
            for(UnlockCatalog.Entry entry:catalog.matchingItems(def.getName()))if(!saved.observed.containsKey(entry.id)) {
                saved.observed.put(entry.id,System.currentTimeMillis());changed=true;
            }
        }
        if(changed){save();dirty=true;}
    }
    private void save()
    {
        if(!profile.isEmpty())configs.setConfiguration("one-man-sync",profile,"unlocksHubProgress",gson.toJson(saved));
    }
    private void publish(UnlockCatalog.Facts facts)
    {
        List<UnlockCatalog.Result> rows=new ArrayList<>();
        StringBuilder signature=new StringBuilder(profile).append(saved.favourites);
        for(UnlockCatalog.Entry entry:catalog.entries) {
            UnlockCatalog.Result row=catalog.evaluate(entry,facts,saved.manual,saved.observed);rows.add(row);
            signature.append(row.state).append(row.detail);
        }
        String key=signature.toString();
        if(key.equals(lastSignature))return;
        lastSignature=key;snapshot=Collections.unmodifiableList(rows);
        favourites=Collections.unmodifiableSet(new HashSet<>(saved.favourites));
        SwingUtilities.invokeLater(()->{if(active&&panel!=null)panel.rebuild();});
    }
    private void change(String account,String id,boolean favourite)
    {
        clientThread.invokeLater(()->{
            if(!active||!accountReady||!profile.equals(account)||!profile.equals(configs.getRSProfileKey()))return;
            UnlockCatalog.Entry entry=catalog.byId.get(id);if(entry==null)return;
            Set<String> set=favourite?saved.favourites:saved.manual;
            if(!favourite&&!entry.manualAllowed())return;
            if(!set.remove(id))set.add(id);
            save();dirty=true;lastTick=Integer.MIN_VALUE;
        });
    }
    List<UnlockCatalog.Result> results() {return snapshot;}
    JPanel companionPanel(){if(panel==null)panel=new Panel();return panel;}

    private final class Panel extends JPanel
    {
        private final JTextField search=new JTextField();
        private final JComboBox<String> filter=new JComboBox<>(new String[]{"All states","To do","Unlocked","Check progress","Requirements missing","Previously seen","Marked complete","Not checked","In progress"});
        private final JCheckBox journal=new JCheckBox("Include quest journal");
        private final JCheckBox favouritesOnly=new JCheckBox("Favourites only");
        private final Map<String,Boolean> expanded=new HashMap<>();
        private final Map<String,Integer> limits=new HashMap<>();
        private final OneManCards list=new OneManCards();
        private final JTextArea summary=OneManCards.text("");
        Panel()
        {
            super(new BorderLayout(0,6));
            OneManCards header=new OneManCards();
            header.card(OneManCards.banner("Unlocks Hub","Find your next unlock"));
            JPanel tools=OneManCards.card();
            OneManCards fields=new OneManCards();search.setName("unlocksSearch");
            search.setToolTipText("Search unlock, category, quest, skill or description");
            fields.card(search);filter.setName("unlocksStatusFilter");fields.card(filter);
            favouritesOnly.setOpaque(false);fields.card(favouritesOnly);journal.setOpaque(false);journal.setSelected(config.unlocksQuestJournal());
            journal.setName("unlocksQuestJournal");fields.card(journal);fields.card(summary);
            tools.add(fields);header.card(tools);add(header,BorderLayout.NORTH);
            add(OneManCards.scroll(list),BorderLayout.CENTER);
            search.getDocument().addDocumentListener(new DocumentListener(){
                public void insertUpdate(DocumentEvent e){rebuild();}public void removeUpdate(DocumentEvent e){rebuild();}public void changedUpdate(DocumentEvent e){rebuild();}
            });
            filter.addActionListener(e->rebuild());favouritesOnly.addActionListener(e->rebuild());
            journal.addActionListener(e->configs.setConfiguration("one-man-sync","unlocksQuestJournal",journal.isSelected()));rebuild();OneManCards.readable(this);
        }
        private boolean matches(UnlockCatalog.Result row,String query)
        {
            if(!config.unlocksQuestJournal()&&"JOURNAL".equals(row.entry.mode))return false;
            if(favouritesOnly.isSelected()&&!favourites.contains(row.entry.id))return false;
            String state=(String)filter.getSelectedItem();
            if("To do".equals(state)&&row.state==UnlockCatalog.State.UNLOCKED)return false;
            if(!"All states".equals(state)&&!"To do".equals(state)&&!row.state.label.equals(state))return false;
            String text=row.entry.title+" "+row.entry.category+" "+row.detail;
            return text.toLowerCase(Locale.ROOT).contains(query);
        }
        void rebuild()
        {
            journal.setSelected(config.unlocksQuestJournal());
            String query=search.getText().trim().toLowerCase(Locale.ROOT);
            Map<String,List<UnlockCatalog.Result>> groups=new LinkedHashMap<>();
            int total=0;
            for(UnlockCatalog.Result row:results()) {
                if(!config.unlocksQuestJournal()&&"JOURNAL".equals(row.entry.mode))continue;
                total++;
                if(matches(row,query))groups.computeIfAbsent(row.entry.category,k->new ArrayList<>()).add(row);
            }
            summary.setText(total+" unlocks");
            list.removeAll();
            for(Map.Entry<String,List<UnlockCatalog.Result>> group:groups.entrySet()) {
                String category=group.getKey();List<UnlockCatalog.Result> rows=group.getValue();
                JPanel card=OneManCards.card();
                boolean open=expanded.getOrDefault(category,!query.isEmpty()||favouritesOnly.isSelected());
                JToggleButton heading=new JToggleButton(category+" ("+rows.size()+")",open);
                heading.setFont(OneManCards.HEADING);
                heading.setText("<html><div style=\"text-align:center\">"+category.replace("&","&amp;")+"<br>"+rows.size()+" unlocks</div></html>");
                heading.setName("unlockCategory:"+category);
                heading.setToolTipText("Expand or collapse "+category);
                heading.addActionListener(e->{expanded.put(category,heading.isSelected());rebuild();});
                card.add(heading,BorderLayout.NORTH);
                if(open) {
                    OneManCards content=new OneManCards();int count=Math.min(rows.size(),limits.getOrDefault(category,15));
                    for(int i=0;i<count;i++)content.card(row(rows.get(i)));
                    if(count<rows.size()) {
                        JButton more=new JButton("Show 15 more ("+(rows.size()-count)+" left)");
                        more.addActionListener(e->{limits.put(category,count+15);rebuild();});content.card(more);
                    }
                    card.add(content,BorderLayout.CENTER);
                }
                list.card(card);
            }
            if(groups.isEmpty())list.card(OneManCards.text("No matching unlocks. Clear the search or change the filters."));
            list.finish();
        }
        private JPanel row(UnlockCatalog.Result result)
        {
            UnlockCatalog.Entry entry=result.entry;String account=profile;
            JPanel card=OneManCards.card();
            JPanel title=new JPanel(new BorderLayout(3,3));title.setOpaque(false);
            JTextArea name=OneManCards.text(UnlockHelp.title(entry));name.setForeground(Color.WHITE);title.add(name,BorderLayout.CENTER);
            JButton star=new JButton(favourites.contains(entry.id)?"★":"☆");star.setMargin(new java.awt.Insets(0,3,0,3));
            star.setToolTipText("Toggle favourite for this account");star.setEnabled(accountReady);
            star.addActionListener(e->change(account,entry.id,true));title.add(star,BorderLayout.EAST);
            card.add(title,BorderLayout.NORTH);
            OneManCards body=new OneManCards();
            JTextArea state=OneManCards.text(UnlockHelp.status(result));
            state.setForeground(result.state==UnlockCatalog.State.UNLOCKED?new Color(100,210,140):result.state==UnlockCatalog.State.PENDING?new Color(225,145,100):OneManCards.ACCENT);
            body.card(state);
            JToggleButton details=new JToggleButton("How to unlock");
            details.setName("unlockDetails:"+entry.id);
            OneManCards expandedDetails=new OneManCards();
            expandedDetails.card(OneManCards.text(UnlockHelp.details(result)));
            JButton guide=new JButton("Open Wiki guide");guide.addActionListener(e->LinkBrowser.browse(entry.wiki));expandedDetails.card(guide);
            if(entry.manualAllowed()&&result.state!=UnlockCatalog.State.OBSERVED) {
                JButton confirm=new JButton(result.state==UnlockCatalog.State.MANUAL?"Undo confirmation":"Confirm manually");
                confirm.setToolTipText("Mark this as complete for this account");confirm.setEnabled(accountReady);
                confirm.addActionListener(e->change(account,entry.id,false));expandedDetails.card(confirm);
            }
            expandedDetails.setVisible(false);details.addActionListener(e->{expandedDetails.setVisible(details.isSelected());revalidate();repaint();});
            body.card(details);body.card(expandedDetails);card.add(body,BorderLayout.CENTER);return card;
        }
    }
}

package lt.oneman.sync;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BirdhouseRunsPanelTest
{
    @Test public void observationStatesKeepTheirExistingTimingAndUnknownSemantics(){
        long seen=1700000000L;
        assertEquals(BirdhouseRun.Status.EMPTY,BirdhouseRun.read(0,"0:"+seen,seen).status);
        assertEquals(BirdhouseRun.Status.NEEDS_SEEDS,BirdhouseRun.read(0,"22:"+seen,seen).status);
        BirdhouseRun growing=BirdhouseRun.read(0,"24:"+seen,seen+1500);
        assertEquals(BirdhouseRun.Status.GROWING,growing.status);assertEquals("Magic Bird House",growing.house);assertEquals(50,growing.progress());assertEquals("25m 0s left",growing.time());
        assertEquals(BirdhouseRun.Status.READY,BirdhouseRun.read(0,"24:"+seen,seen+3000).status);
        assertEquals("Estimated ready",BirdhouseRun.read(0,"24:"+seen,seen+3000).label());
        for(String raw:new String[]{null,"","bad","3:0","28:"+seen,"-1:"+seen,"3:bad","3:1:extra"})assertEquals(BirdhouseRun.Status.UNKNOWN,BirdhouseRun.read(0,raw,seen).status);
    }
    @Test public void fourStableCardsFitNarrowSidebarAndClearOnLogout()throws Exception{
        SwingUtilities.invokeAndWait(()->{
            BirdhouseRunsPanel panel=new BirdhouseRunsPanel(null,()->{});panel.setSize(242,600);
            List<BirdhouseRun> runs=Arrays.asList(BirdhouseRun.read(0,"24:1700000000",1700003000),BirdhouseRun.read(1,"24:1700000000",1700001500),BirdhouseRun.read(2,"22:1700000000",1700001500),BirdhouseRun.unknown(3));
            panel.update(runs,"In progress");layout(panel);fits(panel);
            JPanel first=find(panel,"birdhouseCard:0",JPanel.class);assertNotNull(first);
            assertEquals("Estimated ready",find(panel,"birdhouseStatus:0",JLabel.class).getText());
            assertTrue(find(panel,"birdhouseDetail:1",JTextArea.class).getText().contains("25m"));
            panel.update(runs,"Complete");assertSame("Refreshes must not detach the user's cards",first,find(panel,"birdhouseCard:0",JPanel.class));
            assertEquals("Complete",find(panel,"farmingContractStatus",JLabel.class).getText());
            panel.loggedOut();assertEquals("Log in",find(panel,"birdhouseStatus:0",JLabel.class).getText());assertEquals("Not checked",find(panel,"farmingContractStatus",JLabel.class).getText());
            for(int i=0;i<4;i++)assertEquals("",find(panel,"birdhouseDetail:"+i,JTextArea.class).getText());layout(panel);fits(panel);
        });
    }
    private static <T extends Component>T find(Container c,String name,Class<T> type){for(Component child:c.getComponents()){
        if(name.equals(child.getName())&&type.isInstance(child))return type.cast(child);if(child instanceof Container){T found=find((Container)child,name,type);if(found!=null)return found;}}
        return null;
    }
    private static void layout(Container c){for(int i=0;i<6;i++)once(c);}private static void once(Container c){c.doLayout();for(Component child:c.getComponents())if(child instanceof Container)once((Container)child);}
    private static void fits(Container c){for(Component child:c.getComponents())if(child.isVisible()){
        assertTrue(child.getClass()+" overflows",child.getX()>=0&&child.getX()+child.getWidth()<=c.getWidth());if(child instanceof Container)fits((Container)child);
    }}
}

package lt.oneman.sync;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.Stage;
import com.google.inject.util.Providers;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Test;
import static org.junit.Assert.*;

/** Validates the actual Guice binding graph without starting or controlling the game client. */
public class ClueHubInjectionTest
{
    private static final class EntryPoint { @javax.inject.Inject ClueHub hub; }

    @Test public void overlaysCannotCreateAnEagerTwoWayInjectionCycle()
    {
        for(Class<?> overlay:new Class<?>[]{ClueGroundOverlay.class,ClueWidgetOverlay.class})
            assertFalse("Eager hub/overlay cycle prevents RuneLite loading OneMan: "+overlay.getSimpleName(),
                eagerlyDependsOn(ClueHub.class,overlay) && eagerlyDependsOn(overlay,ClueHub.class));
    }
    private static boolean eagerlyDependsOn(Class<?> owner,Class<?> dependency)
    {
        for(com.google.inject.spi.InjectionPoint point:com.google.inject.spi.InjectionPoint.forInstanceMethodsAndFields(owner))
            for(com.google.inject.spi.Dependency<?> field:point.getDependencies())
                if(field.getKey().getTypeLiteral().getRawType()==dependency) return true;
        return false;
    }

    @Test public void hubAndBothOverlaysBuildWithoutRecursiveConstructorLoad()
    {
        // Binding validation does not provision the live-client providers.
        Injector injector=Guice.createInjector(Stage.TOOL,new AbstractModule()
        {
            @Override protected void configure()
            {
                bind(Client.class).toProvider(Providers.of(null));
                bind(ClientThread.class).toProvider(Providers.of(null));
                bind(ConfigManager.class).toProvider(Providers.of(null));
                bind(ItemManager.class).toProvider(Providers.of(null));
                bind(OverlayManager.class).toProvider(Providers.of(null));
                bind(OneManSyncConfig.class).toInstance(new OneManSyncConfig(){});
            }
        });
        Injector child=injector.createChildInjector(new AbstractModule()
        {
            @Override protected void configure() { bind(EntryPoint.class).toInstance(new EntryPoint()); }
        });
        assertNotNull(child.getBinding(ClueHub.class));
        assertNotNull(child.getBinding(ClueGroundOverlay.class));
        assertNotNull(child.getBinding(ClueWidgetOverlay.class));
    }
}

package lt.oneman.sync;

import java.util.EnumSet;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClueItemCatalogTest
{
    @Test public void emoteTextsResolveAgainstInstalledRuneLite()
    {
        assertEquals("Update the bundled texts when RuneLite changes emote clues", 0, new ClueItemCatalog().unresolvedSteps());
    }
    @Test public void requiredItemsSupportAlternativesAndMultipleTiers()
    {
        ClueItemCatalog data = new ClueItemCatalog();
        assertTrue(data.classify(ItemID.GOLD_RING, "Gold ring").required.contains(ClueTier.BEGINNER));
        assertTrue(data.classify(ItemID.ABYSSAL_WHIP, "Abyssal whip").required.contains(ClueTier.MASTER));
        assertTrue(data.classify(ItemID.LEATHER_CHAPS, "Leather chaps").required.containsAll(EnumSet.of(ClueTier.BEGINNER, ClueTier.EASY)));
        assertTrue(data.classify(ItemID.IBANSTAFF_UPGRADED, "Iban's staff (u)").required.contains(ClueTier.MASTER));
        assertTrue("empty-slot checks must not match unrelated items", data.classify(ItemID.COINS, "Coins").required.isEmpty());
    }
    @Test public void knownRewardsHaveCorrectTiersAndCommonRewardsAreOptional()
    {
        ClueItemCatalog data = new ClueItemCatalog();
        assertEquals(EnumSet.of(ClueTier.BEGINNER), data.rewardTiers("Mole slippers", false));
        assertEquals(EnumSet.of(ClueTier.MEDIUM), data.rewardTiers("Ranger boots", false));
        assertTrue(data.rewardTiers("3rd age platebody", false).containsAll(EnumSet.of(ClueTier.HARD, ClueTier.ELITE, ClueTier.MASTER)));
        ClueItemCatalog.Tags coins = data.classify(ItemID.COINS, "Coins");
        assertTrue(coins.visible(true, true, false).isEmpty());
        assertFalse(coins.visible(true, true, true).isEmpty());
    }
    @Test public void clueContainersRecognizeTierWithoutTaggingUnrelatedItems()
    {
        assertEquals(ClueTier.BEGINNER, ClueTier.scrollTier("Clue scroll (beginner)"));
        assertEquals(ClueTier.MASTER, ClueTier.scrollTier("Reward casket (master)"));
        assertEquals(ClueTier.HARD, ClueTier.scrollTier("Clue geode (hard)"));
        assertNull(ClueTier.scrollTier("Master wand"));
        assertNull(ClueTier.scrollTier("Clue hunter boots"));
    }
}

package lt.oneman.sync;

import org.junit.Test;
import static org.junit.Assert.*;

public class ClueRewardCaptureTest
{
    @Test public void completionThenFreshContainerAndDuplicateMessage()
    {
        ClueRewardCapture capture = new ClueRewardCapture();
        assertFalse(capture.completion("You have completed 12 hard Treasure Trails.", 10));
        assertTrue(capture.containerChanged(11));
        assertEquals(ClueTier.HARD, capture.tier());
        capture.consumed();
        assertFalse(capture.completion("You have completed 12 hard Treasure Trails.", 11));
        assertFalse(capture.containerChanged(12));
    }
    @Test public void reversedEventOrderIsAcceptedOnlyForTheSameTick()
    {
        ClueRewardCapture capture = new ClueRewardCapture();
        assertFalse(capture.containerChanged(10));
        assertTrue(capture.completion("You have completed 1 beginner Treasure Trail.", 10));
        assertEquals(ClueTier.BEGINNER, capture.tier());
        capture.consumed();
        assertFalse(capture.completion("You have completed 2 beginner Treasure Trails.", 11));
    }
    @Test public void staleBarrowsContainerIsNotReusedAndPendingCompletionExpires()
    {
        ClueRewardCapture capture = new ClueRewardCapture();
        capture.containerChanged(1);
        assertFalse(capture.completion("You have completed 20 elite Treasure Trails.", 10));
        capture.tick(16);
        assertNull(capture.tier());
        assertFalse(capture.containerChanged(17));
    }
    @Test public void accountChangeClearsPendingAndDeduplication()
    {
        ClueRewardCapture capture = new ClueRewardCapture();
        String message = "You have completed 1 master Treasure Trail.";
        capture.completion(message, 10); capture.clear();
        assertFalse(capture.containerChanged(11));
        assertTrue(capture.completion(message, 11));
        assertEquals(ClueTier.MASTER, capture.tier());
        assertFalse(capture.completion("Other player: I got a reward casket!", 11));
    }
}

