package lt.oneman.sync;

import java.util.*;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.*;

public class UnlockCatalogTest
{
    private final UnlockCatalog catalog=new UnlockCatalog();
    private UnlockCatalog.State state(String id,UnlockCatalog.Facts facts) {
        return catalog.evaluate(catalog.byId.get(id),facts,Collections.emptySet(),Collections.emptyMap()).state;
    }
    @Test public void comprehensiveCatalogIsUniqueAndEveryQuestHasItsOwnJournalEntry()
    {
        assertEquals(catalog.entries.size(),catalog.byId.size());
        assertTrue(catalog.entries.size()>400);
        for(Quest quest:Quest.values())assertTrue(catalog.byId.containsKey("QUEST_"+quest.name()));
        assertTrue(catalog.entries.stream().filter(e->"ITEM".equals(e.mode)).count()>80);
        assertEquals(48,catalog.entries.stream().filter(e->"DIARY".equals(e.mode)).count());
    }
    @Test public void questCompletionDoesNotProveItemOwnershipAndHistoricalObservationIsSeparate()
    {
        UnlockCatalog.Facts facts=new UnlockCatalog.Facts();facts.live=true;
        facts.quests.put(Quest.RECIPE_FOR_DISASTER__CULINAROMANCER,QuestState.FINISHED);
        assertEquals(UnlockCatalog.State.READY,state("BARROWS_GLOVES",facts));
        UnlockCatalog.Result result=catalog.evaluate(catalog.byId.get("BARROWS_GLOVES"),facts,Collections.emptySet(),Collections.singletonMap("BARROWS_GLOVES",1700000000000L));
        assertEquals(UnlockCatalog.State.OBSERVED,result.state);
        assertTrue(result.detail.contains("not proof of current ownership"));
        assertEquals(UnlockCatalog.State.MANUAL,catalog.evaluate(catalog.byId.get("BARROWS_GLOVES"),facts,Collections.singleton("BARROWS_GLOVES"),Collections.emptyMap()).state);
    }
    @Test public void fairyPermissionCanBeUnlockedBeforeFinishingTheQuest()
    {
        UnlockCatalog.Facts facts=new UnlockCatalog.Facts();facts.live=true;
        facts.quests.put(Quest.FAIRYTALE_II__CURE_A_QUEEN,QuestState.IN_PROGRESS);
        facts.bits.put(VarbitID.FAIRYRING_PERMISSION,1);
        assertEquals(UnlockCatalog.State.UNLOCKED,state("FAIRY_RINGS",facts));
        assertEquals(UnlockCatalog.State.STARTED,state("QUEST_FAIRYTALE_II__CURE_A_QUEEN",facts));
    }
    @Test public void unknownSignalsAndLogoutNeverBecomeFalseCompletionOrCrossAccountNotes()
    {
        UnlockCatalog.Facts facts=new UnlockCatalog.Facts();facts.live=true;
        assertEquals(UnlockCatalog.State.UNKNOWN,state("ANCIENTS",facts));
        assertEquals(UnlockCatalog.State.UNKNOWN,state("RIGOUR",facts));
        facts.live=false;
        assertEquals(UnlockCatalog.State.UNKNOWN,catalog.evaluate(catalog.byId.get("GRACEFUL"),facts,Collections.singleton("GRACEFUL"),Collections.emptyMap()).state);
    }
    @Test public void skillGateAndManualConfirmationRemainDistinct()
    {
        UnlockCatalog.Facts facts=new UnlockCatalog.Facts();facts.live=true;
        facts.skills.put(Skill.FARMING,44);
        assertEquals(UnlockCatalog.State.PENDING,state("FARM_GUILD_45",facts));
        facts.skills.put(Skill.FARMING,45);
        assertEquals(UnlockCatalog.State.READY,state("FARM_GUILD_45",facts));
        facts.quests.put(Quest.DESERT_TREASURE_I,QuestState.FINISHED);
        assertEquals(UnlockCatalog.State.UNLOCKED,state("ANCIENTS",facts));
    }
    @Test public void diaryLegacyValuesAndRewardClaimStatusesAreNotInterchangeable()
    {
        UnlockCatalog.Facts facts=new UnlockCatalog.Facts();facts.live=true;
        UnlockCatalog.Entry karamja=catalog.byId.get("DIARY_Karamja_Easy");
        facts.bits.put(karamja.varbit,1);
        assertEquals(UnlockCatalog.State.PENDING,state(karamja.id,facts));
        facts.bits.put(karamja.varbit,2);
        assertEquals(UnlockCatalog.State.UNLOCKED,state(karamja.id,facts));
        facts.bits.put(VarbitID.CA_TIER_STATUS_EASY,1);
        assertEquals(UnlockCatalog.State.READY,state("CA_Easy",facts));
        facts.bits.put(VarbitID.CA_TIER_STATUS_EASY,2);
        assertEquals(UnlockCatalog.State.UNLOCKED,state("CA_Easy",facts));
    }
    @Test public void chargedItemMatchingNeverTreatsOneGracefulPieceAsAFullSet()
    {
        assertTrue(catalog.matchingItems("Black mask (10)").stream().anyMatch(e->e.id.equals("BLACK_MASK")));
        assertFalse(catalog.matchingItems("Graceful hood").stream().anyMatch(e->e.id.equals("GRACEFUL")));
        assertTrue(catalog.matchingItems("Barrows gloves").stream().anyMatch(e->e.id.equals("BARROWS_GLOVES")));
        assertTrue(catalog.matchingItems("Dragon defender ornament kit").isEmpty());
    }
}

package lt.oneman.sync;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class UnlockHelpTest
{
    private final UnlockCatalog catalog=new UnlockCatalog();
    @Test public void redDragonsShowPurchaseAndCostWithoutDeveloperDiagnostics()
    {
        UnlockCatalog.Entry entry=catalog.byId.get("SLAYER_REDDRAGONS");
        UnlockCatalog.Result result=new UnlockCatalog.Result(entry,UnlockCatalog.State.PENDING,"Source: game completion / purchase flag\nPurchase flag only; task eligibility, current toggles and stored tasks are separate.");
        assertTrue(UnlockHelp.title(entry).contains("Seeing Red"));
        assertEquals("Locked · 50 Slayer points",UnlockHelp.status(result));
        assertTrue(UnlockHelp.details(result).contains("Slayer master → Rewards → Unlock"));
        assertFalse(UnlockHelp.details(result).contains("flag"));
        assertFalse(UnlockHelp.details(result).contains("Source:"));
        assertEquals("Unlocked",UnlockHelp.status(new UnlockCatalog.Result(entry,UnlockCatalog.State.UNLOCKED,"")));
    }
    @Test public void historicalItemEvidenceIsNotPresentedAsCurrentOwnershipOrRawTimestamps()
    {
        UnlockCatalog.Facts facts=new UnlockCatalog.Facts();facts.live=true;
        UnlockCatalog.Result result=catalog.evaluate(catalog.byId.get("FIRE_CAPE"),facts,Collections.emptySet(),Collections.singletonMap("FIRE_CAPE",1700000000000L));
        assertEquals("Previously seen",UnlockHelp.status(result));
        assertFalse(UnlockHelp.details(result).contains("2023-"));
        assertFalse(UnlockHelp.details(result).contains("Source:"));
        assertTrue(UnlockHelp.details(result).contains("Fight Caves"));
    }
    @Test public void retiredSeparateMithrilTaskIsNotOfferedAsAPurchase()
    {
        assertFalse(catalog.byId.containsKey("SLAYER_MITHRIL"));
    }
}

package lt.oneman.sync;

import com.google.gson.GsonBuilder;
import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.*;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class UnlocksHubTest
{
    @Test public void accountChangesAndLogoutClearManualAndItemEvidenceWithoutWritingToOtherAccounts()
    {
        Client client=mock(Client.class);ConfigManager configs=mock(ConfigManager.class);ItemManager items=mock(ItemManager.class);
        AtomicReference<String> profile=new AtomicReference<>("account-a");AtomicInteger tick=new AtomicInteger(100);
        when(configs.getRSProfileKey()).thenAnswer(call->profile.get());
        when(configs.getConfiguration("one-man-sync","account-a","unlocksHubProgress"))
            .thenReturn("{\"manual\":[\"GRACEFUL\"],\"favourites\":[\"FAIRY_RINGS\"],\"observed\":{}}");
        when(client.getTickCount()).thenAnswer(call->tick.getAndIncrement());
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getIntStack()).thenReturn(new int[]{1});
        Player player=mock(Player.class);when(player.getName()).thenReturn("First account");when(client.getLocalPlayer()).thenReturn(player);
        UnlocksHub hub=Guice.createInjector(new AbstractModule() {
            @Override protected void configure() {
                bind(Client.class).toInstance(client);
                bind(ClientThread.class).toInstance(mock(ClientThread.class));
                bind(ConfigManager.class).toInstance(configs);
                bind(ItemManager.class).toInstance(items);
                bind(OneManSyncConfig.class).toInstance(new OneManSyncConfig(){});
                bind(com.google.gson.Gson.class).toInstance(new GsonBuilder().create());
            }
        }).getInstance(UnlocksHub.class);
        try {
            hub.startUp();for(int i=0;i<9;i++)hub.onGameTick();
            assertEquals(UnlockCatalog.State.MANUAL,find(hub,"GRACEFUL").state);
            ItemComposition gloves=mock(ItemComposition.class);
            when(gloves.getName()).thenReturn("Barrows gloves");when(gloves.getNote()).thenReturn(-1);when(gloves.getPlaceholderTemplateId()).thenReturn(-1);
            when(items.getItemComposition(123)).thenReturn(gloves);
            ItemContainer bank=mock(ItemContainer.class);when(bank.getItems()).thenReturn(new Item[]{new Item(123,1)});
            hub.onItemContainerChanged(new ItemContainerChanged(InventoryID.BANK,bank));
            tick.addAndGet(20);hub.onGameTick();
            assertEquals(UnlockCatalog.State.OBSERVED,find(hub,"BARROWS_GLOVES").state);
            verify(configs).setConfiguration(eq("one-man-sync"),eq("account-a"),eq("unlocksHubProgress"),anyString());
            profile.set("account-b");when(player.getName()).thenReturn("Second account");hub.onGameTick();
            assertEquals(UnlockCatalog.State.READY,find(hub,"GRACEFUL").state);
            assertFalse(find(hub,"BARROWS_GLOVES").state==UnlockCatalog.State.OBSERVED);
            verify(configs,never()).setConfiguration(eq("one-man-sync"),eq("account-b"),eq("unlocksHubProgress"),anyString());
            GameStateChanged logout=new GameStateChanged();logout.setGameState(GameState.LOGIN_SCREEN);
            hub.onGameStateChanged(logout);
            assertTrue(hub.results().stream().allMatch(row->row.state==UnlockCatalog.State.UNKNOWN));
        } finally {hub.shutDown();}
    }
    @Test public void missingProfileDoesNotReadOrWriteProgress()
    {
        Client client=mock(Client.class);ConfigManager configs=mock(ConfigManager.class);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);when(client.getLocalPlayer()).thenReturn(mock(Player.class));
        UnlocksHub hub=Guice.createInjector(new AbstractModule() {
            @Override protected void configure() {
                bind(Client.class).toInstance(client);bind(ClientThread.class).toInstance(mock(ClientThread.class));
                bind(ConfigManager.class).toInstance(configs);bind(ItemManager.class).toInstance(mock(ItemManager.class));
                bind(OneManSyncConfig.class).toInstance(new OneManSyncConfig(){});bind(com.google.gson.Gson.class).toInstance(new GsonBuilder().create());
            }
        }).getInstance(UnlocksHub.class);
        try {hub.startUp();for(int i=0;i<20;i++)hub.onGameTick();assertTrue(hub.results().stream().allMatch(row->row.state==UnlockCatalog.State.UNKNOWN));}
        finally {hub.shutDown();}
        verify(configs,never()).getConfiguration(anyString(),anyString(),anyString());
    }
    private UnlockCatalog.Result find(UnlocksHub hub,String id)
    {
        return hub.results().stream().filter(row->row.entry.id.equals(id)).findFirst().get();
    }
}
